insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Incumbe ainda à autoridade policial: fornecer às autoridades judiciárias as informações necessárias à instrução e ao julgamento; realizar as diligências requisitadas pelo juiz ou pelo Ministério Público; cumprir os mandados de prisão expedidos pelas autoridades judiciárias; e representar acerca da prisão preventiva.', '["Fornecer informações ao Judiciário.","Realizar diligências requisitadas pelo juiz ou Ministério Público.","Cumprir mandados de prisão.","Representar pela prisão preventiva."]'::jsonb, '["A autoridade policial REPRESENTA pela preventiva; quem decreta é o juiz."]'::jsonb, 'Delegado representa ao juiz pela prisão preventiva do investigado.', '["Assertiva que atribui à autoridade policial o poder de decretar a prisão preventiva erra: ela representa."]'::jsonb, '[]'::jsonb, '["Art. 311"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-13'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos crimes de sequestro e cárcere privado, redução à condição análoga à de escravo, tráfico de pessoas, extorsão com restrição da liberdade da vítima, extorsão mediante sequestro e no art. 239 do Estatuto da Criança e do Adolescente, o membro do Ministério Público ou o delegado de polícia pode requisitar, de órgãos do poder público ou de empresas privadas, dados e informações cadastrais da vítima ou de suspeitos. A requisição será atendida no prazo de 24 horas e conterá o nome da autoridade requisitante, o número do inquérito policial e a identificação da unidade de polícia judiciária responsável.', '["Requisição de dados cadastrais da vítima ou de suspeitos por MP ou delegado.","Crimes: arts. 148, 149, 149-A, 158 §3º, 159 do CP e art. 239 do ECA.","Prazo de atendimento: 24 horas.","A requisição indica a autoridade, o número do inquérito e a unidade responsável."]'::jsonb, '["Dados cadastrais; o conteúdo de comunicação depende de ordem judicial."]'::jsonb, 'Delegado requisita dados cadastrais de suspeito de extorsão mediante sequestro.', '["Assertiva que fixa o prazo de atendimento em 72 horas erra: são 24 horas."]'::jsonb, '[]'::jsonb, '["Art. 13-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-13-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se necessário à prevenção e à repressão dos crimes relacionados ao tráfico de pessoas, o membro do Ministério Público ou o delegado de polícia podem requisitar, mediante autorização judicial, às empresas de telecomunicações e/ou telemática que disponibilizem imediatamente os meios técnicos adequados, como sinais e informações, que permitam localizar a vítima ou os suspeitos do delito em curso. Sinal significa posicionamento da estação de cobertura, setorização e intensidade de radiofrequência. O sinal não permite acesso ao conteúdo da comunicação, será fornecido por período não superior a 30 dias, renovável uma única vez por igual período; períodos superiores exigem ordem judicial. O inquérito deverá ser instaurado em até 72 horas do registro da ocorrência. Se não houver manifestação judicial em 12 horas, a autoridade competente requisitará os meios, com imediata comunicação ao juiz.', '["Requisição às operadoras para localizar vítima ou suspeitos, mediante autorização judicial.","Sinal: estação de cobertura, setorização e intensidade de radiofrequência.","Sem acesso ao conteúdo da comunicação.","Fornecimento por até 30 dias, renovável por igual período, uma única vez.","Inquérito instaurado em até 72 horas.","Sem manifestação judicial em 12 horas, a autoridade requisita, comunicando ao juiz."]'::jsonb, '["Prazos: 30 dias (renovável uma vez), 72 horas para o inquérito, 12 horas para a manifestação judicial."]'::jsonb, 'Delegado, com autorização judicial, requisita o sinal do celular de vítima de tráfico de pessoas.', '["Assertiva que permite o acesso ao conteúdo das comunicações pelo mero sinal erra."]'::jsonb, '[]'::jsonb, '["Art. 13-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-13-b'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

