select u.id, u.content_sha256, 'O ofendido, ou seu representante legal, e o indiciado podem requerer qualquer diligência, que será realizada, ou não, a juízo da autoridade.', '["Ofendido, representante legal e indiciado podem requerer diligências.","A autoridade decide se realiza ou não."]'::jsonb, '["Exceção: o exame de corpo de delito, quando a infração deixa vestígios, é obrigatório (art. 158)."]'::jsonb, 'A vítima requer a oitiva de uma testemunha, e a autoridade decide se o faz.', '["Assertiva que obriga a autoridade a realizar qualquer diligência requerida pelo indiciado erra."]'::jsonb, '[]'::jsonb, '["Art. 158"]'::jsonb, 'under_review', 'claude'
