insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando servidores das instituições do art. 144 da Constituição figurarem como investigados em inquéritos policiais, inquéritos policiais militares e procedimentos extrajudiciais sobre fatos relacionados ao uso da força letal praticados no exercício profissional, de forma consumada ou tentada, incluindo as situações do art. 23 do Código Penal, o indiciado pode constituir defensor. O investigado será citado da instauração e poderá constituir defensor em até 48 horas. Esgotado o prazo sem nomeação, a autoridade intimará a instituição a que o investigado estava vinculado, para que, em 48 horas, indique defensor. Havendo necessidade de defesa técnica, a escolha recairá preferencialmente na Defensoria Pública; onde não houver, a União ou a Unidade da Federação disponibilizará profissional. Na ausência da Defensoria, os custos correm por conta do orçamento da instituição a que o investigado estava vinculado. Aplica-se aos militares do art. 142 da Constituição em missões de Garantia da Lei e da Ordem.', '["Aplica-se a servidores do art. 144 da Constituição investigados por uso da força letal.","Citação do investigado e prazo de 48 horas para constituir defensor.","Sem defensor, a instituição indica um em 48 horas.","Preferência pela Defensoria Pública.","Custos da defesa, na ausência da Defensoria, correm por conta da instituição.","Estende-se a militares em missões de Garantia da Lei e da Ordem."]'::jsonb, '["Prazos de 48 horas para constituir e para indicar defensor."]'::jsonb, 'Policial investigado por morte em serviço é citado e tem 48 horas para constituir defensor.', '["Assertiva que fixa em 24 horas o prazo para o investigado constituir defensor erra: são 48 horas."]'::jsonb, '[]'::jsonb, '["Art. 23 do Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-14-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

