insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o ofendido for menor de 21 e maior de 18 anos, o direito de queixa poderá ser exercido por ele ou por seu representante legal. O dispositivo é considerado revogado de modo tácito pelo Código Civil, que fixou a maioridade em 18 anos.', '["Ofendido entre 18 e 21 anos: queixa por ele ou pelo representante legal.","Dispositivo superado pela maioridade civil."]'::jsonb, '["Tema histórico: o Código Civil unificou a maioridade aos 18 anos."]'::jsonb, 'Hoje, aos 18 anos, o ofendido já exerce sozinho o direito de queixa.', '["Assertiva que exige representante legal para o ofendido de 18 anos exercer a queixa erra, pois a regra foi superada."]'::jsonb, '[]'::jsonb, '["Art. 33"]'::jsonb, 'under_review', 'claude'
