insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se comparecer mais de uma pessoa com direito de queixa, terá preferência o cônjuge e, em seguida, o parente mais próximo na ordem do art. 31. Qualquer delas poderá, entretanto, prosseguir na ação caso o querelante desista da instância ou a abandone.', '["Preferência: cônjuge, depois o parente mais próximo na ordem do art. 31.","Qualquer delas pode prosseguir na ação se o querelante desistir ou abandonar."]'::jsonb, '["Regra de preferência entre legitimados sucessivos."]'::jsonb, 'Cônjuge e irmão pretendem queixa: o cônjuge tem preferência.', '["Assertiva que dá preferência ao irmão sobre o cônjuge erra."]'::jsonb, '[]'::jsonb, '["Art. 31"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-36'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As fundações, associações ou sociedades legalmente constituídas podem exercer a ação penal, devendo ser representadas por quem os respectivos contratos ou estatutos designarem ou, no silêncio destes, pelos seus diretores ou sócios-gerentes.', '["Pessoas jurídicas podem ajuizar ação penal privada.","Representação: conforme contrato ou estatuto; no silêncio, diretores ou sócios-gerentes."]'::jsonb, '["A pessoa jurídica pode ser querelante (por exemplo, em crime contra a honra, quando ofendida)."]'::jsonb, 'Associação ofendida ajuíza queixa-crime representada por seu diretor.', '["Assertiva que nega à pessoa jurídica capacidade de ser querelante erra."]'::jsonb, '[]'::jsonb, '["Art. 30"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-37'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Salvo disposição em contrário, o ofendido ou seu representante legal decai do direito de queixa ou de representação se não o exercer dentro do prazo de seis meses, contado do dia em que vier a saber quem é o autor do crime, ou, no caso do art. 29, do dia em que se esgotar o prazo para o oferecimento da denúncia. A decadência também se verifica, no mesmo prazo, nos casos do art. 24, parágrafo único, e do art. 31. Nos crimes de violência doméstica e familiar contra a mulher, o prazo é de 12 meses, contados do mesmo modo.', '["Prazo geral: seis meses, a partir do conhecimento da autoria.","Ação subsidiária: conta do fim do prazo para a denúncia.","§1º: vale também para os casos dos arts. 24 e 31.","§2º: violência doméstica e familiar contra a mulher: 12 meses."]'::jsonb, '["O prazo conta da ciência da AUTORIA, e não do fato.","No caso de violência doméstica e familiar contra a mulher, o prazo é de 12 meses (Lei nº 15.438, de 2026)."]'::jsonb, 'Vítima de crime de ação privada tem seis meses, desde que soube quem é o autor, para ajuizar a queixa.', '["Assertiva que conta o prazo decadencial da data do fato erra: conta da ciência da autoria."]'::jsonb, '[{"termo":"Decadência","significado":"Perda do direito de queixa ou de representação por decurso do prazo."}]'::jsonb, '["Art. 29","Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-38'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O direito de representação pode ser exercido pessoalmente ou por procurador com poderes especiais, mediante declaração, escrita ou oral, feita ao juiz, ao órgão do Ministério Público ou à autoridade policial. A representação oral ou escrita sem assinatura autenticada será reduzida a termo, perante o juiz ou autoridade policial, presente o Ministério Público se a ele dirigida. Conterá todas as informações que sirvam à apuração do fato e da autoria. Oferecida ou reduzida a termo a representação, a autoridade policial procede a inquérito ou, não sendo competente, o remete à autoridade que o for. Se feita ao juiz, é remetida à autoridade policial. O Ministério Público dispensará o inquérito, se com a representação forem oferecidos elementos que o habilitem a promover a ação penal, e, neste caso, oferecerá a denúncia no prazo de quinze dias.', '["Representação pessoal ou por procurador com poderes especiais.","Dirigida ao juiz, ao Ministério Público ou à autoridade policial.","Pode ser escrita ou oral; sem assinatura autenticada, reduz-se a termo.","Conteúdo: informações sobre o fato e a autoria.","Autoridade policial procede ao inquérito.","§5º: MP dispensa o inquérito se há elementos e denuncia em quinze dias."]'::jsonb, '["Não exige formalidade rígida: basta manifestar a vontade de ver o autor processado."]'::jsonb, 'Vítima diz, em delegacia, que quer ver o autor processado: a representação é reduzida a termo.', '["Assertiva que exige forma escrita e solene para a representação erra: pode ser oral, reduzida a termo."]'::jsonb, '[]'::jsonb, '["Art. 24","Art. 25"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-39'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando, em autos ou papéis de que conhecerem, os juízes ou tribunais verificarem a existência de crime de ação pública, remeterão ao Ministério Público as cópias e os documentos necessários ao oferecimento da denúncia.', '["Juízes e tribunais que verifiquem crime de ação pública remetem cópias ao Ministério Público.","Para que seja oferecida a denúncia."]'::jsonb, '["O juiz não inicia a ação penal: provoca o Ministério Público."]'::jsonb, 'Juiz cível percebe indício de falsidade e envia cópias ao MP.', '["Assertiva que permite ao juiz instaurar a ação penal de ofício, segundo o art. 40, erra: ele remete ao Ministério Público."]'::jsonb, '[]'::jsonb, '["Art. 27"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-40'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A denúncia ou queixa conterá a exposição do fato criminoso, com todas as suas circunstâncias, a qualificação do acusado ou esclarecimentos pelos quais se possa identificá-lo, a classificação do crime e, quando necessário, o rol das testemunhas.', '["Exposição do fato criminoso com todas as circunstâncias.","Qualificação do acusado ou dados de identificação.","Classificação do crime.","Rol de testemunhas, quando necessário."]'::jsonb, '["Denúncia inepta é rejeitada se faltar descrição do fato ou da autoria."]'::jsonb, 'Denúncia descreve data, local e modo da conduta e identifica o acusado.', '["Assertiva que dispensa a descrição das circunstâncias do fato na denúncia erra."]'::jsonb, '[]'::jsonb, '["Art. 395"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-41'
