insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Ministério Público não pode desistir da ação penal (princípio da indisponibilidade).', '["Indisponibilidade da ação penal pública."]'::jsonb, '["O MP pode pedir a absolvição nas alegações finais, mas não desistir da ação."]'::jsonb, 'Mesmo convencido da inocência, o MP não desiste; pede a absolvição.', '["Assertiva que permite ao MP desistir da ação penal pública erra."]'::jsonb, '[{"termo":"Indisponibilidade","significado":"Iniciada a ação pública, o MP não pode abrir mão dela."}]'::jsonb, '["Art. 576"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-42'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A queixa poderá ser dada por procurador com poderes especiais, devendo constar do instrumento do mandato o nome do querelante e a menção do fato criminoso, salvo quando tais esclarecimentos dependerem de diligências que devem ser previamente requeridas no juízo criminal.', '["Queixa por procurador com poderes especiais.","Mandato deve conter o nome do querelante e a menção do fato criminoso.","Exceção: esclarecimentos dependentes de diligências prévias."]'::jsonb, '["Procuração sem menção ao fato pode gerar nulidade sanável."]'::jsonb, 'Advogado com procuração específica ajuíza a queixa-crime.', '["Assertiva que dispensa poderes especiais na procuração da queixa erra."]'::jsonb, '[]'::jsonb, '["Art. 30"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-44'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A queixa, ainda quando a ação penal for privativa do ofendido, poderá ser aditada pelo Ministério Público, a quem caberá intervir em todos os termos subsequentes do processo.', '["MP pode aditar a queixa.","MP intervém em todos os termos do processo."]'::jsonb, '["O MP atua como fiscal da lei na ação privada."]'::jsonb, 'MP adita a queixa para incluir circunstância do fato.', '["Assertiva que impede o MP de atuar na ação privada erra."]'::jsonb, '[]'::jsonb, '["Art. 29"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-45'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O prazo para oferecimento da denúncia, estando o réu preso, é de 5 dias, contado da data em que o Ministério Público receber os autos do inquérito, e de 15 dias, se o réu estiver solto ou afiançado. Se houver devolução do inquérito à autoridade policial (art. 16), o prazo conta da data em que o MP receber novamente os autos. Se o MP dispensar o inquérito, o prazo conta da data em que tiver recebido as peças de informação ou a representação. O prazo para aditamento da queixa é de 3 dias; se o MP não se pronunciar, entende-se que não tem o que aditar.', '["Réu preso: 5 dias.","Réu solto ou afiançado: 15 dias.","Devolução do inquérito: prazo conta do novo recebimento.","Dispensa do inquérito: conta do recebimento das peças de informação.","Aditamento da queixa: 3 dias; silêncio vale como nada a aditar."]'::jsonb, '["Prazos impróprios: o descumprimento autoriza a ação privada subsidiária, e não a nulidade."]'::jsonb, 'Réu preso: o MP tem 5 dias para denunciar.', '["Assertiva que fixa em 15 dias o prazo da denúncia com réu preso erra: são 5 dias."]'::jsonb, '[]'::jsonb, '["Art. 16","Art. 29"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-46'
