insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o Ministério Público julgar necessários maiores esclarecimentos, documentos complementares ou novos elementos de convicção, deverá requisitá-los, diretamente, de quaisquer autoridades ou funcionários que devam ou possam fornecê-los.', '["O MP requisita diretamente esclarecimentos e documentos a autoridades e funcionários."]'::jsonb, '["Poder de requisição direta do Ministério Público."]'::jsonb, 'MP requisita documentos de um órgão público para embasar a denúncia.', '["Assertiva que exige ordem judicial para o MP requisitar documentos nos termos do art. 47 erra."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-47'
