insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A queixa contra qualquer dos autores do crime obrigará ao processo de todos, e o Ministério Público velará pela sua indivisibilidade.', '["Princípio da indivisibilidade da ação privada.","Queixa contra um obriga ao processo de todos.","MP vela pela indivisibilidade."]'::jsonb, '["Não se aplica à ação penal pública (STF)."]'::jsonb, 'O querelante não pode escolher processar só um dos coautores.', '["Assertiva que permite ao querelante escolher livremente quais autores processar erra."]'::jsonb, '[{"termo":"Indivisibilidade","significado":"Se processa todos os autores ou nenhum."}]'::jsonb, '["Art. 49"]'::jsonb, 'under_review', 'claude'
