insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A renúncia ao exercício do direito de queixa, em relação a um dos autores do crime, a todos se estenderá.', '["Renúncia a um se estende a todos os autores."]'::jsonb, '["Consequência da indivisibilidade."]'::jsonb, 'Ofendido renuncia à queixa contra um coautor e perde o direito contra os demais.', '["Assertiva que limita a renúncia ao autor beneficiado erra: estende-se a todos."]'::jsonb, '[{"termo":"Renúncia","significado":"Abrir mão do direito de queixa antes da ação."}]'::jsonb, '["Art. 48","Art. 50"]'::jsonb, 'under_review', 'claude'
