select u.id, u.content_sha256, 'No caso de morte do acusado, o juiz somente à vista da certidão de óbito, e depois de ouvido o Ministério Público, declarará extinta a punibilidade.', '["Morte do acusado: extinção da punibilidade.","Exige certidão de óbito e oitiva do Ministério Público."]'::jsonb, '["A prova da morte é a certidão de óbito."]'::jsonb, 'Com a certidão de óbito nos autos, o juiz declara extinta a punibilidade.', '["Assertiva que dispensa a certidão de óbito para extinguir a punibilidade erra."]'::jsonb, '[]'::jsonb, '["Art. 61"]'::jsonb, 'under_review', 'claude'
