insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Antes de transitar em julgado a sentença final, as coisas apreendidas não poderão ser restituídas enquanto interessarem ao processo.', '["Coisas apreendidas não são restituídas antes do trânsito, enquanto interessarem ao processo."]'::jsonb, '["Critério: interesse para o processo."]'::jsonb, 'A arma usada no crime fica apreendida até o fim do processo.', '["Assertiva que determina a restituição imediata das coisas apreendidas erra: elas ficam retidas enquanto interessarem ao processo."]'::jsonb, '[]'::jsonb, '["Art. 119","Art. 120"]'::jsonb, 'under_review', 'claude'
