insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Procede-se ao sequestro dos bens móveis se, verificadas as condições previstas no art. 126, não for cabível a medida de busca e apreensão regulada no Capítulo XI do Título VII deste Livro.', '["Sequestro de bens móveis, quando preenchidas as condições do art. 126.","Subsidiário à busca e apreensão."]'::jsonb, '["Subsidiariedade: só se não couber busca e apreensão."]'::jsonb, 'Bem móvel obtido com proventos do crime e que não comporta busca e apreensão é sequestrado.', '["Assertiva que torna o sequestro de bens móveis preferencial à busca e apreensão erra: é subsidiário."]'::jsonb, '[]'::jsonb, '["Art. 126"]'::jsonb, 'under_review', 'claude'
