select u.id, u.content_sha256, 'Os interessados ou, nos casos do art. 142, o Ministério Público poderão requerer no juízo cível, contra o responsável civil, as medidas previstas nos arts. 134, 136 e 137.', '["As medidas assecuratórias podem ser requeridas no juízo cível contra o responsável civil."]'::jsonb, '["Pode alcançar o RESPONSÁVEL CIVIL (por exemplo, empregador)."]'::jsonb, 'Vítima requer no cível hipoteca legal contra o responsável civil pelo ato do preposto.', '["Assertiva que limita as medidas assecuratórias ao autor do crime erra: alcançam o responsável civil."]'::jsonb, '[]'::jsonb, '["Art. 142"]'::jsonb, 'under_review', 'claude'
