insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz determinará a alienação antecipada para preservação do valor dos bens sempre que estiverem sujeitos a qualquer grau de deterioração ou depreciação, ou quando houver dificuldade para sua manutenção. O leilão será preferencialmente eletrônico. Os bens serão vendidos pelo valor da avaliação judicial ou por valor maior; se não alcançado, haverá novo leilão em até 10 dias, podendo os bens ser alienados por valor não inferior a 80% da avaliação. O produto da alienação fica depositado em conta vinculada ao juízo até a decisão final, convertendo-se em renda para a União, Estado ou Distrito Federal no caso de condenação ou sendo devolvido ao acusado no caso de absolvição. Quando a indisponibilidade recair sobre dinheiro, moeda estrangeira, títulos, valores mobiliários ou cheques, o juízo determina a conversão em moeda nacional corrente e o depósito em conta judicial, entre outras providências do dispositivo.', '["Alienação antecipada para preservar o valor de bens sujeitos a deterioração ou de difícil manutenção.","Leilão preferencialmente eletrônico.","Venda pelo valor da avaliação ou superior; novo leilão em até 10 dias, com piso de 80% da avaliação.","Produto depositado em conta vinculada ao juízo até a decisão final.","Condenação: conversão em renda do ente; absolvição: devolução ao acusado."]'::jsonb, '["Segundo leilão: até 10 dias e valor mínimo de 80% da avaliação."]'::jsonb, 'Veículo apreendido que se deprecia é leiloado antecipadamente, e o dinheiro fica depositado.', '["Assertiva que fixa o valor mínimo do segundo leilão em 50% da avaliação erra: é 80%."]'::jsonb, '[]'::jsonb, '["Art. 133"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-144-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Arguida, por escrito, a falsidade de documento constante dos autos, o juiz observará o seguinte processo: autua em apartado a impugnação e ouve a parte contrária, que responde em 48 horas; assina três dias, sucessivamente, a cada parte, para prova de suas alegações; conclusos os autos, pode ordenar diligências; e, se reconhecida a falsidade por decisão irrecorrível, manda desentranhar o documento e remetê-lo, com os autos do incidente, ao Ministério Público.', '["Arguição de falsidade por escrito.","Autuação em apartado; resposta da parte contrária em 48 horas.","Três dias sucessivos para prova.","Diligências pelo juiz.","Falsidade reconhecida por decisão irrecorrível: desentranhamento e remessa ao MP."]'::jsonb, '["Prazos: 48 horas para a resposta e três dias para a prova."]'::jsonb, 'A defesa argui por escrito a falsidade de um documento dos autos, e o incidente tramita em apartado.', '["Assertiva que permite arguir a falsidade apenas oralmente erra: a arguição é escrita."]'::jsonb, '[]'::jsonb, '["Art. 146","Art. 147","Art. 148"]'::jsonb, 'under_review', 'claude'
