insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz formará sua convicção pela livre apreciação da prova produzida em contraditório judicial, não podendo fundamentar sua decisão exclusivamente nos elementos informativos colhidos na investigação, ressalvadas as provas cautelares, não repetíveis e antecipadas. Somente quanto ao estado das pessoas serão observadas as restrições estabelecidas na lei civil.', '["Livre apreciação da prova (livre convencimento motivado).","Prova produzida em contraditório judicial.","Elementos do inquérito não bastam sozinhos.","Exceções: provas cautelares, não repetíveis e antecipadas.","Restrições da lei civil apenas quanto ao estado das pessoas."]'::jsonb, '["Sentença não pode se apoiar EXCLUSIVAMENTE no inquérito.","Provas cautelares, não repetíveis e antecipadas têm valor."]'::jsonb, 'Perícia não repetível feita no inquérito pode embasar a condenação.', '["Assertiva que permite condenar com base apenas em elementos informativos do inquérito erra."]'::jsonb, '[{"termo":"Livre convencimento motivado","significado":"O juiz avalia a prova livremente, mas fundamenta a decisão."}]'::jsonb, '["Art. 156","Art. 157"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-155'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A prova da alegação incumbe a quem a fizer, sendo, porém, facultado ao juiz, de ofício, ordenar, mesmo antes de iniciada a ação penal, a produção antecipada de provas consideradas urgentes e relevantes, observando a necessidade, adequação e proporcionalidade da medida; e determinar, no curso da instrução ou antes de proferir sentença, a realização de diligências para dirimir dúvida sobre ponto relevante.', '["Ônus da prova de quem alega.","Juiz pode ordenar, de ofício, produção antecipada de provas urgentes e relevantes (observada a proporcionalidade).","Pode determinar diligências para dirimir dúvida sobre ponto relevante."]'::jsonb, '["O inciso I (prova antes da ação penal) é objeto de discussão em ADIs; confira a situação atual.","Atuação supletiva do juiz, não substitutiva da acusação."]'::jsonb, 'Juiz determina diligência para esclarecer ponto relevante antes de sentenciar.', '["Assertiva que impede qualquer iniciativa probatória do juiz erra: o art. 156 a prevê de forma supletiva."]'::jsonb, '[]'::jsonb, '["Art. 3º-A","Art. 155"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-156'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São inadmissíveis, devendo ser desentranhadas do processo, as provas ilícitas, assim entendidas as obtidas em violação a normas constitucionais ou legais. São também inadmissíveis as provas derivadas das ilícitas, salvo quando não evidenciado o nexo de causalidade entre umas e outras, ou quando as derivadas puderem ser obtidas por uma fonte independente. Considera-se fonte independente aquela que por si só, seguindo os trâmites típicos da investigação ou instrução criminal, seria capaz de conduzir ao fato objeto da prova. Preclusa a decisão de desentranhamento, a prova será inutilizada por decisão judicial, facultado às partes acompanhar o incidente. O juiz que conhecer do conteúdo da prova declarada inadmissível não poderá proferir a sentença ou acórdão.', '["Provas ilícitas são inadmissíveis e desentranhadas.","Provas derivadas também (teoria dos frutos da árvore envenenada), com exceções.","Exceções: ausência de nexo causal; fonte independente.","Inutilização da prova após a preclusão do desentranhamento.","§5º: juiz que conheceu o conteúdo da prova ilícita não sentencia."]'::jsonb, '["§5º sujeito a discussão em ADIs: confira a situação atual.","Fonte independente é aquela capaz de, por si só, levar ao fato."]'::jsonb, 'Prova obtida por interceptação ilegal é desentranhada, e as provas dela derivadas também.', '["Assertiva que admite sempre as provas derivadas das ilícitas erra: há exceções (nexo e fonte independente)."]'::jsonb, '[{"termo":"Fonte independente","significado":"Origem autônoma que conduziria ao fato por si só."}]'::jsonb, '["Art. 155"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-157'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando a infração deixar vestígios, será indispensável o exame de corpo de delito, direto ou indireto, não podendo supri-lo a confissão do acusado. Dar-se-á prioridade ao exame de corpo de delito quando se tratar de crime que envolva violência doméstica e familiar contra mulher, ou violência contra criança, adolescente, idoso ou pessoa com deficiência.', '["Infração com vestígios: exame de corpo de delito indispensável (direto ou indireto).","A confissão não supre o exame.","Prioridade: violência doméstica e familiar contra a mulher; violência contra criança, adolescente, idoso ou pessoa com deficiência."]'::jsonb, '["A confissão NÃO substitui o exame.","Se os vestígios desaparecem, a prova testemunhal pode suprir (art. 167)."]'::jsonb, 'Em lesão corporal, o laudo pericial é necessário e a confissão não o substitui.', '["Assertiva que permite suprir o exame de corpo de delito pela confissão do acusado erra."]'::jsonb, '[{"termo":"Exame de corpo de delito","significado":"Perícia sobre os vestígios materiais da infração."}]'::jsonb, '["Art. 167"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-158'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Considera-se cadeia de custódia o conjunto de todos os procedimentos utilizados para manter e documentar a história cronológica do vestígio coletado em locais ou em vítimas de crimes, para rastrear sua posse e manuseio a partir de seu reconhecimento até o descarte. O início da cadeia dá-se com a preservação do local de crime ou com procedimentos policiais ou periciais nos quais seja detectada a existência de vestígio. O agente público que reconhecer um elemento como de potencial interesse para a produção da prova pericial fica responsável por sua preservação. Vestígio é todo objeto ou material bruto, visível ou latente, constatado ou recolhido, que se relaciona à infração penal.', '["Cadeia de custódia: procedimentos para documentar a história do vestígio, do reconhecimento ao descarte.","Início: preservação do local ou procedimentos em que se detecta o vestígio.","Agente que reconhece o elemento fica responsável por preservá-lo.","Vestígio: objeto ou material bruto, visível ou latente, relacionado à infração."]'::jsonb, '["Incluído pela Lei nº 13.964, de 2019 (Pacote Anticrime).","Quebra da cadeia de custódia pode comprometer a prova."]'::jsonb, 'A arma encontrada na cena é registrada, lacrada e documentada em todas as etapas.', '["Assertiva que inicia a cadeia de custódia apenas com a entrega ao laboratório erra: começa com a preservação do local ou o reconhecimento do vestígio."]'::jsonb, '[{"termo":"Vestígio","significado":"Todo objeto ou material relacionado à infração penal."}]'::jsonb, '["Art. 158-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-158-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A cadeia de custódia compreende o rastreamento do vestígio nas etapas de reconhecimento (distinguir o elemento de potencial interesse para a prova pericial); isolamento (evitar a alteração do estado das coisas, preservando o ambiente imediato, mediato e relacionado); fixação (descrição detalhada do vestígio como se encontra, podendo ser ilustrada por fotografias, filmagens ou croqui, sendo indispensável sua descrição no laudo); coleta (recolher o vestígio, respeitando suas características e natureza); acondicionamento (embalar cada vestígio de forma individualizada, com anotação da data, hora e nome de quem coletou e acondicionou); e as demais etapas previstas no dispositivo, como transporte, recebimento, processamento, armazenamento e descarte.', '["Reconhecimento.","Isolamento.","Fixação (descrição, fotografias, filmagens ou croqui).","Coleta.","Acondicionamento individualizado, com data, hora e nome.","Seguem transporte, recebimento, processamento, armazenamento e descarte."]'::jsonb, '["Dez etapas; saiba a ordem e o conceito de cada."]'::jsonb, 'O perito fotografa e descreve o vestígio (fixação) antes da coleta.', '["Assertiva que coloca a coleta antes do isolamento erra: a ordem é reconhecimento, isolamento, fixação e coleta."]'::jsonb, '[]'::jsonb, '["Art. 158-A","Art. 158-C"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-158-b'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A coleta dos vestígios deverá ser realizada preferencialmente por perito oficial, que dará o encaminhamento necessário para a central de custódia, mesmo quando for necessária a realização de exames complementares. Todos os vestígios coletados no decurso do inquérito ou processo devem ser tratados como descrito na lei, ficando o órgão central de perícia oficial de natureza criminal responsável por detalhar a forma do seu cumprimento. É proibida a entrada em locais isolados bem como a remoção de quaisquer vestígios de locais de crime antes da liberação por parte do perito responsável, sendo tipificada como fraude processual a sua realização.', '["Coleta preferencialmente por perito oficial.","Encaminhamento à central de custódia.","Órgão central de perícia detalha o cumprimento.","Proibido entrar no local isolado ou remover vestígios antes da liberação do perito.","Violação configura fraude processual."]'::jsonb, '["Remover vestígio antes da liberação pelo perito = FRAUDE PROCESSUAL."]'::jsonb, 'Curioso entra na cena do crime isolada e retira um objeto antes da liberação: fraude processual.', '["Assertiva que autoriza a remoção de vestígios por qualquer agente antes da liberação do perito erra."]'::jsonb, '[]'::jsonb, '["Art. 158-B","Art. 347 do Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-158-c'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O recipiente para acondicionamento do vestígio será determinado pela natureza do material. Todos os recipientes deverão ser selados com lacres, com numeração individualizada, de forma a garantir a inviolabilidade e a idoneidade do vestígio durante o transporte. O recipiente deverá individualizar o vestígio, preservar suas características, impedir contaminação e vazamento, ter grau de resistência adequado e espaço para registro de informações sobre seu conteúdo. Só poderá ser aberto pelo perito que vai proceder à análise e, motivadamente, por pessoa autorizada. Após cada rompimento de lacre, devem constar na ficha de acompanhamento do vestígio o nome e a matrícula do responsável, a data, o local, a finalidade e as informações do novo lacre. O lacre rompido será acondicionado no interior do novo recipiente.', '["Recipiente conforme a natureza do material.","Lacres com numeração individualizada.","Recipiente individualiza o vestígio, evita contaminação e tem espaço para registro.","Só o perito que analisa (ou pessoa autorizada, motivadamente) abre.","Cada rompimento de lacre é registrado na ficha.","Lacre rompido guardado no novo recipiente."]'::jsonb, '["Registro de cada rompimento de lacre."]'::jsonb, 'Cada vez que o lacre é rompido, a ficha de acompanhamento registra quem, quando e por quê.', '["Assertiva que permite a qualquer servidor abrir o recipiente do vestígio erra: só o perito responsável ou pessoa autorizada, motivadamente."]'::jsonb, '[]'::jsonb, '["Art. 158-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-158-d'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Todos os Institutos de Criminalística deverão ter uma central de custódia destinada à guarda e controle dos vestígios, e sua gestão deve ser vinculada diretamente ao órgão central de perícia oficial de natureza criminal. Toda central deve possuir serviços de protocolo, com local para conferência, recepção, devolução de materiais e documentos, em espaço seguro e com condições ambientais que não interfiram nas características do vestígio. A entrada e a saída de vestígio devem ser protocoladas; todas as pessoas com acesso ao vestígio devem ser identificadas, com data e hora; e todas as ações de tramitação devem ser registradas.', '["Central de custódia em todo Instituto de Criminalística, vinculada ao órgão central de perícia.","Serviço de protocolo e espaço seguro.","Entrada e saída protocoladas.","Identificação de quem acessa, com data e hora.","Registro de todas as ações de tramitação."]'::jsonb, '["Gestão vinculada ao órgão central de perícia oficial."]'::jsonb, 'Quem acessa o vestígio armazenado é identificado e registrado com data e hora.', '["Assertiva que vincula a central de custódia à polícia militar erra: é vinculada ao órgão central de perícia."]'::jsonb, '[]'::jsonb, '["Art. 158-D"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-158-e'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Após a realização da perícia, o material deverá ser devolvido à central de custódia, devendo nela permanecer. Caso a central não possua espaço ou condições de armazenar determinado material, a autoridade policial ou judiciária determinará as condições de depósito em local diverso, mediante requerimento do diretor do órgão central de perícia oficial de natureza criminal.', '["Material devolvido à central de custódia após a perícia.","Sem espaço: depósito em outro local, determinado pela autoridade, a requerimento do diretor do órgão central de perícia."]'::jsonb, '["Devolução à central depois da perícia."]'::jsonb, 'Material volumoso é depositado em local diverso por decisão da autoridade.', '["Assertiva que permite ao perito escolher o local de depósito sem decisão da autoridade erra."]'::jsonb, '[]'::jsonb, '["Art. 158-E"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-158-f'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O exame de corpo de delito e outras perícias serão realizados por perito oficial, portador de diploma de curso superior. Na falta de perito oficial, o exame será realizado por 2 pessoas idôneas, portadoras de diploma de curso superior preferencialmente na área específica, dentre as que tiverem habilitação técnica relacionada com a natureza do exame. Os peritos não oficiais prestarão o compromisso de bem e fielmente desempenhar o encargo. É facultada ao Ministério Público, ao assistente de acusação, ao ofendido, ao querelante e ao acusado a formulação de quesitos e a indicação de assistente técnico. O assistente técnico atua a partir de sua admissão pelo juiz e após a conclusão dos exames e elaboração do laudo pelos peritos oficiais, sendo as partes intimadas desta decisão. Durante o curso do processo judicial, é permitido às partes requerer a oitiva dos peritos e indicar assistentes técnicos, nos termos do dispositivo.', '["Regra: um perito oficial com curso superior.","Sem perito oficial: 2 pessoas idôneas com curso superior.","Peritos não oficiais prestam compromisso.","Partes formulam quesitos e indicam assistente técnico.","Assistente técnico atua após o laudo dos oficiais.","Partes podem requerer a oitiva dos peritos."]'::jsonb, '["Exige diploma de curso superior.","Assistente técnico atua após o laudo."]'::jsonb, 'Na falta de perito oficial, duas pessoas idôneas com diploma superior fazem o exame.', '["Assertiva que dispensa diploma de curso superior para o perito oficial erra."]'::jsonb, '[]'::jsonb, '["Art. 160"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-159'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os peritos elaborarão o laudo pericial, onde descreverão minuciosamente o que examinarem e responderão aos quesitos formulados. O laudo pericial será elaborado no prazo máximo de 10 dias, podendo este prazo ser prorrogado, em casos excepcionais, a requerimento dos peritos.', '["Laudo descreve minuciosamente o exame e responde aos quesitos.","Prazo máximo de 10 dias.","Prorrogação excepcional, a requerimento dos peritos."]'::jsonb, '["Prazo: 10 dias."]'::jsonb, 'Perito pede prorrogação do prazo de 10 dias para o laudo, em caso excepcional.', '["Assertiva que fixa em 30 dias o prazo do laudo erra: são 10 dias."]'::jsonb, '[]'::jsonb, '["Art. 159"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-160'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O exame de corpo de delito poderá ser feito em qualquer dia e a qualquer hora.', '["Exame de corpo de delito em qualquer dia e hora."]'::jsonb, '["Não há restrição de horário."]'::jsonb, 'Exame realizado em feriado ou de madrugada é válido.', '["Assertiva que limita o exame de corpo de delito a dias úteis erra."]'::jsonb, '[]'::jsonb, '["Art. 158"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-161'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autópsia será feita pelo menos seis horas depois do óbito, salvo se os peritos, pela evidência dos sinais de morte, julgarem que possa ser feita antes daquele prazo, o que declararão no auto. Nos casos de morte violenta, bastará o simples exame externo do cadáver quando não houver infração penal a apurar, ou quando as lesões externas permitirem precisar a causa da morte e não houver necessidade de exame interno.', '["Autópsia pelo menos seis horas após o óbito.","Antes, se a evidência dos sinais de morte permitir, declarado no auto.","Morte violenta: pode bastar o exame externo em hipóteses específicas."]'::jsonb, '["Seis horas, salvo evidência dos sinais de morte."]'::jsonb, 'Perito conclui antecipadamente a autópsia por evidência dos sinais de morte e declara no auto.', '["Assertiva que fixa em 24 horas o prazo mínimo para a autópsia erra: são seis horas."]'::jsonb, '[]'::jsonb, '["Art. 158"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-162'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em caso de exumação para exame cadavérico, a autoridade providenciará para que, em dia e hora previamente marcados, se realize a diligência, da qual se lavrará auto circunstanciado. O administrador de cemitério público ou particular indicará o lugar da sepultura, sob pena de desobediência. No caso de recusa ou falta de quem indique a sepultura, ou de encontrar-se o cadáver em lugar não destinado a inumações, a autoridade procederá às pesquisas necessárias, o que constará do auto.', '["Exumação em dia e hora previamente marcados, com auto circunstanciado.","Administrador do cemitério indica a sepultura, sob pena de desobediência.","Recusa ou ausência de indicação: autoridade faz as pesquisas e registra no auto."]'::jsonb, '["Recusa do administrador pode configurar desobediência."]'::jsonb, 'Cemitério se recusa a indicar a sepultura, e a autoridade realiza pesquisas e lavra auto.', '["Assertiva que dispensa a lavratura do auto circunstanciado na exumação erra."]'::jsonb, '[{"termo":"Exumação","significado":"Retirada do cadáver da sepultura para exame."}]'::jsonb, '["Art. 162"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-163'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os cadáveres serão sempre fotografados na posição em que forem encontrados, bem como, na medida do possível, todas as lesões externas e vestígios deixados no local do crime.', '["Cadáveres fotografados na posição em que foram encontrados.","Lesões externas e vestígios, na medida do possível."]'::jsonb, '["Registro fotográfico obrigatório."]'::jsonb, 'A equipe fotografa o corpo na posição original e as lesões visíveis.', '["Assertiva que dispensa fotografias do cadáver na posição em que foi encontrado erra."]'::jsonb, '[]'::jsonb, '["Art. 165"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-164'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para representar as lesões encontradas no cadáver, os peritos, quando possível, juntarão ao laudo do exame provas fotográficas, esquemas ou desenhos, devidamente rubricados.', '["Representação das lesões por fotografias, esquemas ou desenhos.","Devidamente rubricados."]'::jsonb, '["Elementos ilustrativos do laudo, quando possível."]'::jsonb, 'Perito anexa croqui rubricado com a localização das lesões.', '["Assertiva que torna proibida a juntada de desenhos ao laudo erra."]'::jsonb, '[]'::jsonb, '["Art. 164"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-165'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Havendo dúvida sobre a identidade do cadáver exumado, proceder-se-á ao reconhecimento pelo Instituto de Identificação e Estatística ou repartição congênere ou pela inquirição de testemunhas, lavrando-se auto de reconhecimento e de identidade, no qual se descreverá o cadáver, com todos os sinais e indicações. Em qualquer caso, serão arrecadados e autenticados todos os objetos encontrados que possam ser úteis para a identificação do cadáver.', '["Dúvida sobre a identidade do cadáver exumado: reconhecimento pelo Instituto de Identificação ou por testemunhas.","Auto de reconhecimento e de identidade.","Objetos úteis à identificação arrecadados e autenticados."]'::jsonb, '["Auto descreve o cadáver com todos os sinais."]'::jsonb, 'Testemunhas reconhecem o cadáver exumado, e se lavra o auto de identidade.', '["Assertiva que dispensa o auto de reconhecimento e de identidade erra."]'::jsonb, '[]'::jsonb, '["Art. 163"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-166'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não sendo possível o exame de corpo de delito por haverem desaparecido os vestígios, a prova testemunhal poderá suprir-lhe a falta.', '["Vestígios desaparecidos: a prova testemunhal pode suprir o exame."]'::jsonb, '["Exame indireto por testemunhas, se os vestígios sumiram."]'::jsonb, 'Lesão sem registro e já curada: testemunhas podem comprovar a materialidade.', '["Assertiva que permite suprir o exame pela confissão, no art. 167, erra: o texto fala em prova testemunhal."]'::jsonb, '[]'::jsonb, '["Art. 158"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-167'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em caso de lesões corporais, se o primeiro exame pericial tiver sido incompleto, proceder-se-á a exame complementar por determinação da autoridade policial ou judiciária, de ofício, ou a requerimento do Ministério Público, do ofendido ou do acusado, ou de seu defensor. No exame complementar, os peritos terão presente o auto de corpo de delito, a fim de suprir-lhe a deficiência ou retificá-lo. Se o exame tiver por fim precisar a classificação do delito no art. 129, §1º, I, do Código Penal (incapacidade para as ocupações habituais por mais de trinta dias), deverá ser feito logo que decorra o prazo de 30 dias, contado da data do crime. A falta de exame complementar poderá ser suprida pela prova testemunhal.', '["Exame complementar quando o primeiro foi incompleto.","Determinado de ofício ou a requerimento.","Peritos têm à vista o primeiro auto.","Para o art. 129, §1º, I: logo que decorra o prazo de 30 dias da data do crime.","Falta do complementar pode ser suprida por testemunhas."]'::jsonb, '["Prazo de 30 dias do crime, para a lesão com incapacidade por mais de 30 dias."]'::jsonb, 'Exame complementar feito após 30 dias para verificar a incapacidade para as ocupações habituais.', '["Assertiva que impede suprir a falta do exame complementar por prova testemunhal erra."]'::jsonb, '[]'::jsonb, '["Art. 158","Art. 129 do Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-168'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para o efeito de exame do local onde houver sido praticada a infração, a autoridade providenciará imediatamente para que não se altere o estado das coisas até a chegada dos peritos, que poderão instruir seus laudos com fotografias, desenhos ou esquemas elucidativos. Os peritos registrarão, no laudo, as alterações do estado das coisas e discutirão, no relatório, as consequências dessas alterações na dinâmica dos fatos.', '["Autoridade preserva o local até a chegada dos peritos.","Laudos podem ter fotografias, desenhos ou esquemas.","Peritos registram as alterações e discutem as consequências."]'::jsonb, '["Preservação do local é imediata."]'::jsonb, 'O local do crime é isolado imediatamente, e o perito registra as alterações encontradas.', '["Assertiva que dispensa o registro, no laudo, das alterações do local erra."]'::jsonb, '[]'::jsonb, '["Art. 6º","Art. 158-C"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-169'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nas perícias de laboratório, os peritos guardarão material suficiente para a eventualidade de nova perícia. Sempre que conveniente, os laudos serão ilustrados com provas fotográficas, ou microfotográficas, desenhos ou esquemas.', '["Material suficiente guardado para eventual nova perícia.","Laudos ilustrados com fotografias, microfotografias, desenhos ou esquemas."]'::jsonb, '["Guarda de material para contraprova."]'::jsonb, 'Perito guarda parte da amostra para uma possível segunda análise.', '["Assertiva que permite consumir toda a amostra na perícia de laboratório erra."]'::jsonb, '[]'::jsonb, '["Art. 159"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-170'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos crimes cometidos com destruição ou rompimento de obstáculo à subtração da coisa, ou por meio de escalada, os peritos, além de descrever os vestígios, indicarão com que instrumentos, por que meios e em que época presumem ter sido o fato praticado.', '["Crimes com destruição ou rompimento de obstáculo, ou escalada.","Peritos descrevem os vestígios e indicam instrumentos, meios e época provável."]'::jsonb, '["Perícia de qualificadora (rompimento de obstáculo, escalada)."]'::jsonb, 'No furto qualificado por rompimento de obstáculo, o perito indica o instrumento usado.', '["Assertiva que dispensa a indicação da época do fato no laudo do art. 171 erra."]'::jsonb, '[]'::jsonb, '["Art. 158"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-171'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Proceder-se-á, quando necessário, à avaliação de coisas destruídas, deterioradas ou que constituam produto do crime. Se impossível a avaliação direta, os peritos procederão à avaliação por meio dos elementos existentes nos autos e dos que resultarem de diligências.', '["Avaliação de coisas destruídas, deterioradas ou produto do crime.","Avaliação indireta, se a direta for impossível."]'::jsonb, '["Avaliação indireta com base nos autos e diligências."]'::jsonb, 'Perito avalia o valor do bem destruído com base em documentos dos autos.', '["Assertiva que impede a avaliação indireta de coisas destruídas erra."]'::jsonb, '[]'::jsonb, '["Art. 159"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-172'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No caso de incêndio, os peritos verificarão a causa e o lugar em que houver começado, o perigo que dele tiver resultado para a vida ou para o patrimônio alheio, a extensão do dano e o seu valor e as demais circunstâncias que interessarem à elucidação do fato.', '["Perícia de incêndio: causa e lugar de origem.","Perigo para a vida ou o patrimônio alheio.","Extensão e valor do dano, e outras circunstâncias."]'::jsonb, '["Relaciona-se ao crime de incêndio (art. 250 do Código Penal)."]'::jsonb, 'Perito do incêndio determina onde o fogo começou e o prejuízo causado.', '["Assertiva que dispensa a verificação do local onde o incêndio começou erra."]'::jsonb, '[]'::jsonb, '["Art. 250 do Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-173'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No exame para o reconhecimento de escritos, por comparação de letra: a pessoa a quem se atribua o escrito será intimada para o ato, se encontrada; para a comparação servem quaisquer documentos que ela reconheça, já judicialmente reconhecidos como de seu punho, ou de autenticidade indiscutível; a autoridade requisitará documentos de arquivos ou estabelecimentos públicos, ou realizará a diligência no local; e, se não houver escritos ou forem insuficientes, mandará que a pessoa escreva o que lhe for ditado, podendo a diligência ser feita por precatória se ela estiver ausente em lugar certo.', '["Intimação da pessoa a quem se atribui o escrito.","Documentos de comparação: reconhecidos, judicialmente reconhecidos ou de autenticidade indiscutível.","Requisição de documentos de arquivos públicos.","Sem escritos suficientes: a pessoa escreve o que lhe for ditado (por precatória, se ausente em lugar certo)."]'::jsonb, '["Ninguém é obrigado a produzir prova contra si: a recusa em escrever sob ditado é discutida pela jurisprudência."]'::jsonb, 'A autoridade pede à pessoa que escreva um texto ditado, para comparar com o documento questionado.', '["Assertiva que dispensa a intimação da pessoa a quem se atribui o escrito, se ela for encontrada, erra."]'::jsonb, '[]'::jsonb, '["Art. 159"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-174'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Serão sujeitos a exame os instrumentos empregados para a prática da infração, a fim de se lhes verificar a natureza e a eficiência.', '["Instrumentos do crime são periciados.","Verifica-se a natureza e a eficiência."]'::jsonb, '["Exemplo: exame de eficiência da arma (potencialidade lesiva)."]'::jsonb, 'A arma usada no crime é submetida a perícia para verificar se funciona.', '["Assertiva que dispensa o exame do instrumento do crime erra."]'::jsonb, '[]'::jsonb, '["Art. 158"]'::jsonb, 'under_review', 'claude'
