insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No caso do §1º do art. 159 (peritos não oficiais), o escrivão lavrará o auto respectivo, que será assinado pelos peritos e, se presente ao exame, também pela autoridade. Nos casos do art. 160, parágrafo único, o laudo, que poderá ser datilografado, será subscrito e rubricado em suas folhas por todos os peritos.', '["Peritos não oficiais: o escrivão lavra o auto, assinado pelos peritos e pela autoridade, se presente.","Laudo subscrito e rubricado em todas as folhas por todos os peritos."]'::jsonb, '["Formalidade da perícia por peritos não oficiais."]'::jsonb, 'Peritos leigos assinam o auto lavrado pelo escrivão.', '["Assertiva que dispensa a rubrica das folhas do laudo erra."]'::jsonb, '[]'::jsonb, '["Art. 159","Art. 160"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-179'
