select u.id, u.content_sha256, 'O juiz não ficará adstrito ao laudo, podendo aceitá-lo ou rejeitá-lo, no todo ou em parte.', '["O juiz não está vinculado ao laudo.","Pode aceitá-lo ou rejeitá-lo, total ou parcialmente."]'::jsonb, '["Sistema liberatório: o laudo não vincula o juiz."]'::jsonb, 'O juiz acolhe parte do laudo e rejeita outra, fundamentando.', '["Assertiva que vincula o juiz ao laudo pericial erra."]'::jsonb, '[]'::jsonb, '["Art. 155"]'::jsonb, 'under_review', 'claude'
