insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Salvo o caso de exame de corpo de delito, o juiz ou a autoridade policial negará a perícia requerida pelas partes quando não for necessária ao esclarecimento da verdade.', '["Perícia requerida pelas partes pode ser negada se desnecessária.","Exceção: exame de corpo de delito não pode ser negado."]'::jsonb, '["Exame de corpo de delito é obrigatório quando há vestígios."]'::jsonb, 'A autoridade nega uma perícia desnecessária requerida pela defesa.', '["Assertiva que permite negar o exame de corpo de delito por desnecessário erra."]'::jsonb, '[]'::jsonb, '["Art. 158"]'::jsonb, 'under_review', 'claude'
