insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o interrogando negar a acusação, no todo ou em parte, poderá prestar esclarecimentos e indicar provas.', '["Acusado que nega a acusação pode prestar esclarecimentos e indicar provas."]'::jsonb, '["Faculdade do acusado."]'::jsonb, 'O acusado nega o crime e indica uma testemunha de álibi.', '["Assertiva que proíbe o acusado de indicar provas no interrogatório erra."]'::jsonb, '[]'::jsonb, '["Art. 190"]'::jsonb, 'under_review', 'claude'
