insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O valor da confissão se aferirá pelos critérios adotados para os outros elementos de prova, e para a sua apreciação o juiz deverá confrontá-la com as demais provas do processo, verificando se entre ela e estas existe compatibilidade ou concordância.', '["Confissão tem valor relativo, como as demais provas.","Deve ser confrontada com o restante da prova."]'::jsonb, '["Não há hierarquia entre provas: a confissão não é a ''rainha das provas''."]'::jsonb, 'O juiz confronta a confissão com a perícia e os depoimentos.', '["Assertiva que atribui valor absoluto à confissão erra."]'::jsonb, '[]'::jsonb, '["Art. 155","Art. 200"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-197'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O silêncio do acusado não importará confissão, mas poderá constituir elemento para a formação do convencimento do juiz. A parte final do dispositivo, que permite valorar o silêncio, é considerada incompatível com a garantia constitucional do direito ao silêncio.', '["Silêncio não é confissão.","A parte final (silêncio como elemento de convencimento) conflita com a Constituição."]'::jsonb, '["Prevalece o art. 186, parágrafo único: o silêncio não pode ser interpretado em prejuízo da defesa."]'::jsonb, 'O silêncio do acusado não pode ser usado para fundamentar a condenação.', '["Assertiva que usa o silêncio como elemento de convencimento contra o acusado erra, à luz do art. 186 e da Constituição."]'::jsonb, '[]'::jsonb, '["Art. 186"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-198'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A confissão, quando feita fora do interrogatório, será tomada por termo nos autos, observado o disposto no art. 195.', '["Confissão extra-interrogatório é reduzida a termo nos autos.","Aplica-se o art. 195 (registro de recusa ou impossibilidade de assinar)."]'::jsonb, '["Confissão extrajudicial tomada por termo."]'::jsonb, 'Acusado confessa por petição, e a confissão é tomada por termo nos autos.', '["Assertiva que dispensa o termo para a confissão fora do interrogatório erra."]'::jsonb, '[]'::jsonb, '["Art. 195"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-199'
