insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A confissão será divisível e retratável, sem prejuízo do livre convencimento do juiz, fundado no exame das provas em conjunto.', '["Confissão divisível: o juiz pode aceitar parte e rejeitar outra.","Confissão retratável: o acusado pode voltar atrás.","Livre convencimento fundado no conjunto das provas."]'::jsonb, '["Divisibilidade e retratabilidade."]'::jsonb, 'O acusado confessa o fato, mas o juiz acolhe só parte da narrativa.', '["Assertiva que torna a confissão irretratável e indivisível erra."]'::jsonb, '[{"termo":"Confissão divisível","significado":"O juiz pode acolher parte da confissão."}]'::jsonb, '["Art. 197"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-200'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Sempre que possível, o ofendido será qualificado e perguntado sobre as circunstâncias da infração, quem seja ou presuma ser o seu autor e as provas que possa indicar, tomando-se por termo as suas declarações. Se, intimado, deixar de comparecer sem motivo justo, poderá ser conduzido à presença da autoridade. Será comunicado dos atos processuais relativos ao ingresso e à saída do acusado da prisão, à designação de data para audiência e à sentença e acórdãos que a mantenham ou modifiquem, no endereço indicado ou por meio eletrônico, por opção sua. Antes do início da audiência e durante sua realização, será reservado espaço separado para o ofendido. O juiz poderá encaminhá-lo para atendimento multidisciplinar (psicossocial, assistência jurídica e saúde), a expensas do ofensor ou do Estado, e tomará providências para preservar a intimidade, vida privada, honra e imagem do ofendido.', '["Declarações do ofendido tomadas por termo.","Condução coercitiva se faltar sem motivo justo.","Comunicação dos atos processuais ao ofendido (prisão, audiência, sentença e acórdãos).","Espaço separado na audiência.","Atendimento multidisciplinar, a expensas do ofensor ou do Estado.","Preservação da intimidade e da imagem."]'::jsonb, '["O ofendido NÃO é testemunha e não presta compromisso."]'::jsonb, 'A vítima é comunicada da saída do acusado da prisão.', '["Assertiva que obriga o ofendido a prestar compromisso de dizer a verdade como as testemunhas erra."]'::jsonb, '[]'::jsonb, '["Art. 203"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-201'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Toda pessoa poderá ser testemunha, salvo as exceções legais: quem pode recusar-se a depor e quem é proibido de fazê-lo.', '["Qualquer pessoa pode ser testemunha."]'::jsonb, '["Ressalvas: pessoas proibidas de depor (art. 207) e dispensadas (art. 206)."]'::jsonb, 'Um vizinho que presenciou o fato pode ser testemunha.', '["Assertiva que restringe a testemunha a maiores de 18 anos erra: toda pessoa pode ser testemunha."]'::jsonb, '[]'::jsonb, '["Art. 206","Art. 207"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-202'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A testemunha fará, sob palavra de honra, a promessa de dizer a verdade do que souber e lhe for perguntado, devendo declarar seu nome, idade, estado, residência, profissão, lugar onde exerce sua atividade, se é parente, e em que grau, de alguma das partes, ou quais suas relações com qualquer delas, e relatar o que souber, explicando sempre as razões de sua ciência ou as circunstâncias pelas quais possa avaliar-se sua credibilidade.', '["Promessa de dizer a verdade sob palavra de honra.","Qualificação e declaração de relações com as partes.","Relata o que sabe e explica a razão de sua ciência."]'::jsonb, '["Explicar a razão da ciência."]'::jsonb, 'A testemunha informa se é parente do acusado antes de depor.', '["Assertiva que dispensa a testemunha de explicar a razão de sua ciência erra."]'::jsonb, '[]'::jsonb, '["Art. 208"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-203'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O depoimento será prestado oralmente, não sendo permitido à testemunha trazê-lo por escrito. Não será vedada à testemunha, entretanto, breve consulta a apontamentos.', '["Depoimento oral.","Vedado trazê-lo por escrito.","Breve consulta a apontamentos é permitida."]'::jsonb, '["Oralidade com breve consulta."]'::jsonb, 'A testemunha consulta rapidamente uma anotação com datas.', '["Assertiva que permite à testemunha depor lendo texto escrito erra."]'::jsonb, '[]'::jsonb, '["Art. 203"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-204'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se ocorrer dúvida sobre a identidade da testemunha, o juiz procederá à verificação pelos meios ao seu alcance, podendo, entretanto, tomar-lhe o depoimento desde logo.', '["Dúvida sobre a identidade: o juiz verifica pelos meios ao seu alcance.","Pode tomar o depoimento desde logo."]'::jsonb, '["Não impede o depoimento imediato."]'::jsonb, 'Juiz colhe o depoimento enquanto confirma a identidade da testemunha.', '["Assertiva que impede o depoimento até a confirmação da identidade erra."]'::jsonb, '[]'::jsonb, '["Art. 203"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-205'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A testemunha não poderá eximir-se da obrigação de depor. Poderão, entretanto, recusar-se a fazê-lo o ascendente ou descendente, o afim em linha reta, o cônjuge (ainda que desquitado), o irmão e o pai, a mãe ou o filho adotivo do acusado, salvo quando não for possível, por outro modo, obter-se ou integrar-se a prova do fato e de suas circunstâncias.', '["Regra: dever de depor.","Podem recusar-se: ascendente, descendente, afim em linha reta, cônjuge, irmão, pais ou filho adotivo do acusado.","Exceção: quando não for possível obter a prova de outro modo."]'::jsonb, '["Os parentes podem recusar-se, mas, se não houver outro meio de prova, devem depor (sem compromisso)."]'::jsonb, 'Irmão do acusado pode se recusar a depor, salvo se não houver outro modo de provar o fato.', '["Assertiva que obriga o cônjuge do acusado a depor em qualquer hipótese erra: ele pode se recusar, salvo quando a prova não puder ser obtida por outro modo."]'::jsonb, '[]'::jsonb, '["Art. 208"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-206'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São proibidas de depor as pessoas que, em razão de função, ministério, ofício ou profissão, devam guardar segredo, salvo se, desobrigadas pela parte interessada, quiserem dar o seu testemunho.', '["Proibição de depor para quem tem dever de sigilo profissional.","Exceção: desobrigadas pela parte interessada e dispostas a depor."]'::jsonb, '["Sigilo profissional (advogado, médico, sacerdote etc.).","Mesmo desobrigada, a pessoa só depõe se QUISER."]'::jsonb, 'Advogado não pode depor sobre segredo de seu cliente, salvo desobrigado por este e querendo depor.', '["Assertiva que obriga a pessoa desobrigada pela parte a depor erra: ela depõe se quiser."]'::jsonb, '[]'::jsonb, '["Art. 214"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-207'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

