select u.id, u.content_sha256, 'Não se deferirá o compromisso a que alude o art. 203 aos doentes e deficientes mentais e aos menores de 14 anos, nem às pessoas a que se refere o art. 206.', '["Sem compromisso: doentes e deficientes mentais, menores de 14 anos e parentes do art. 206."]'::jsonb, '["Quem depõe sem compromisso não comete falso testemunho."]'::jsonb, 'Criança de 10 anos depõe sem prestar compromisso.', '["Assertiva que exige compromisso do menor de 14 anos erra."]'::jsonb, '[{"termo":"Informante","significado":"Quem depõe sem compromisso de dizer a verdade."}]'::jsonb, '["Art. 203","Art. 206"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-208'
