insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando houver necessidade de fazer-se o reconhecimento de pessoa, procede-se assim: a pessoa que tiver de fazer o reconhecimento é convidada a descrever a pessoa a ser reconhecida; esta será colocada, se possível, ao lado de outras que tiverem qualquer semelhança, convidando-se quem faz o reconhecimento a apontá-la; se houver razão para recear que a pessoa chamada não diga a verdade em face da que deve ser reconhecida, por intimidação ou outra influência, a autoridade providenciará para que esta não veja aquela; do ato lavra-se auto pormenorizado, subscrito pela autoridade, pela pessoa que reconheceu e por duas testemunhas presenciais. O inciso III não se aplica na instrução criminal ou em plenário.', '["I: descrição prévia da pessoa a ser reconhecida.","II: colocação ao lado de pessoas semelhantes, se possível.","III: se houver receio de intimidação, a pessoa a reconhecer não vê a reconhecenda.","IV: auto pormenorizado, subscrito pela autoridade, pelo reconhecedor e por duas testemunhas.","Parágrafo único: o inciso III não se aplica na instrução ou no plenário."]'::jsonb, '["O STJ tem exigido a observância do procedimento do art. 226 sob pena de invalidade do reconhecimento.","O parágrafo único afasta o inciso III na instrução e no plenário."]'::jsonb, 'A vítima descreve o autor e depois o aponta entre pessoas parecidas.', '["Assertiva que dispensa a descrição prévia pela pessoa que fará o reconhecimento erra."]'::jsonb, '[]'::jsonb, '["Art. 227","Art. 228"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-226'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

