select u.id, u.content_sha256, 'No reconhecimento de objeto, proceder-se-á com as cautelas estabelecidas no artigo anterior, no que for aplicável.', '["Reconhecimento de objeto segue as cautelas do art. 226, no que couber."]'::jsonb, '["Aplicação subsidiária das regras do reconhecimento de pessoas."]'::jsonb, 'Vítima descreve o objeto subtraído antes de reconhecê-lo entre outros semelhantes.', '["Assertiva que dispensa as cautelas do art. 226 no reconhecimento de objeto erra."]'::jsonb, '[]'::jsonb, '["Art. 226"]'::jsonb, 'under_review', 'claude'
