insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A busca será domiciliar ou pessoal. A busca domiciliar, quando fundadas razões a autorizarem, serve para prender criminosos; apreender coisas achadas ou obtidas por meios criminosos; apreender instrumentos de falsificação ou contrafação e objetos falsificados; apreender armas, munições e instrumentos utilizados na prática de crime; descobrir objetos necessários à prova da infração ou à defesa do réu; apreender cartas destinadas ao acusado ou em seu poder, quando houver suspeita de que o conteúdo seja útil à elucidação do fato; apreender pessoas vítimas de crimes; e colher qualquer elemento de convicção. A busca pessoal ocorrerá quando houver fundada suspeita de que alguém oculte consigo arma proibida ou os objetos das letras b a f e h do parágrafo anterior.', '["Busca domiciliar ou pessoal.","Domiciliar: fundadas razões; finalidades das alíneas a a h.","Pessoal: fundada suspeita de arma proibida ou dos objetos listados."]'::jsonb, '["Exige FUNDADAS razões (domiciliar) e FUNDADA SUSPEITA (pessoal).","A Constituição protege o domicílio (art. 5º, XI)."]'::jsonb, 'Busca domiciliar para apreender arma usada no crime, com fundadas razões.', '["Assertiva que permite a busca pessoal sem fundada suspeita erra."]'::jsonb, '[]'::jsonb, '["Art. 241","Art. 244"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-240'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando a própria autoridade policial ou judiciária não a realizar pessoalmente, a busca domiciliar deverá ser precedida da expedição de mandado.', '["Busca domiciliar por terceiros exige mandado.","A autoridade que a realiza pessoalmente fica dispensada do mandado pelo texto, mas a Constituição exige ordem judicial."]'::jsonb, '["Na Constituição, a busca domiciliar de dia exige ordem judicial; o dispositivo deve ser lido à luz dela."]'::jsonb, 'O delegado cumpre o mandado de busca expedido pelo juiz.', '["Assertiva que dispensa mandado para a busca domiciliar realizada por agentes subordinados erra."]'::jsonb, '[]'::jsonb, '["Art. 243"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-241'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A busca poderá ser determinada de ofício ou a requerimento de qualquer das partes.', '["Busca determinada de ofício ou a requerimento das partes."]'::jsonb, '["Mesmo de ofício, deve respeitar a Constituição e o sistema acusatório."]'::jsonb, 'A defesa requer busca para localizar documento útil à sua tese.', '["Assertiva que restringe o pedido de busca ao Ministério Público erra: qualquer das partes pode requerer."]'::jsonb, '[]'::jsonb, '["Art. 240"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-242'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O mandado de busca deverá indicar, o mais precisamente possível, a casa em que será realizada a diligência e o nome do respectivo proprietário ou morador, ou, no caso de busca pessoal, o nome da pessoa ou os sinais que a identifiquem; mencionar o motivo e os fins da diligência; e ser subscrito pelo escrivão e assinado pela autoridade que o fizer expedir. Se houver ordem de prisão, constará do próprio texto do mandado de busca. Não será permitida a apreensão de documento em poder do defensor do acusado, salvo quando constituir elemento do corpo de delito.', '["Indicar a casa e o morador (ou a pessoa, na busca pessoal).","Mencionar motivo e fins.","Subscrito pelo escrivão e assinado pela autoridade.","Ordem de prisão consta do próprio mandado.","Documentos em poder do defensor não podem ser apreendidos, salvo se forem corpo de delito."]'::jsonb, '["Proteção do sigilo profissional do advogado."]'::jsonb, 'O mandado indica precisamente o endereço e a finalidade da busca.', '["Assertiva que permite a apreensão de qualquer documento em poder do defensor erra."]'::jsonb, '[]'::jsonb, '["Art. 240","Art. 245"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-243'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A busca pessoal independerá de mandado, no caso de prisão ou quando houver fundada suspeita de que a pessoa esteja na posse de arma proibida ou de objetos ou papéis que constituam corpo de delito, ou quando a medida for determinada no curso de busca domiciliar.', '["Busca pessoal sem mandado em caso de prisão.","Ou fundada suspeita de arma proibida ou corpo de delito.","Ou no curso de busca domiciliar."]'::jsonb, '["Exige FUNDADA SUSPEITA, baseada em elementos concretos, e não mero estereótipo."]'::jsonb, 'Policial, com fundada suspeita, revista pessoa que esconde arma proibida.', '["Assertiva que exige mandado para toda busca pessoal erra."]'::jsonb, '[]'::jsonb, '["Art. 240, §2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-244'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As buscas domiciliares serão executadas de dia, salvo se o morador consentir que se realizem à noite, e, antes de penetrarem na casa, os executores mostrarão e lerão o mandado ao morador, ou a quem o represente, intimando-o a abrir a porta. Se a própria autoridade der a busca, declarará previamente sua qualidade e o objeto da diligência. Em caso de desobediência, será arrombada a porta e forçada a entrada. Recalcitrando o morador, será permitido o emprego de força contra coisas existentes no interior da casa. Ausentes os moradores, será intimado a assistir à diligência qualquer vizinho presente. Se determinada a pessoa ou coisa a procurar, o morador será intimado a mostrá-la. Descoberta, será imediatamente apreendida e posta sob custódia. Finda a diligência, lavra-se auto circunstanciado, assinado com duas testemunhas presenciais.', '["Busca de dia, salvo consentimento do morador para a noite.","Mostrar e ler o mandado antes de entrar e intimar a abrir a porta.","Desobediência: arrombamento da porta.","Morador recalcitrante: força contra coisas.","Ausência de moradores: vizinho assiste.","Auto circunstanciado com duas testemunhas."]'::jsonb, '["Dia/noite: a Constituição permite o ingresso sem consentimento, com ordem judicial, apenas de dia."]'::jsonb, 'A equipe lê o mandado ao morador e o intima a abrir a porta antes de entrar.', '["Assertiva que autoriza a busca domiciliar à noite com mandado, sem consentimento do morador, erra."]'::jsonb, '[]'::jsonb, '["Art. 243","Art. 246"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-245'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aplicar-se-á também o disposto no artigo anterior quando se tiver de proceder a busca em compartimento habitado ou em aposento ocupado de habitação coletiva ou em compartimento não aberto ao público, onde alguém exercer profissão ou atividade.', '["As regras do art. 245 valem para compartimento habitado ou aposento ocupado de habitação coletiva.","Também para compartimento não aberto ao público onde se exerce profissão ou atividade."]'::jsonb, '["Conceito amplo de ''casa'' (STF)."]'::jsonb, 'Escritório profissional fechado ao público equipara-se à casa para fins de busca.', '["Assertiva que exclui o escritório profissional da proteção do domicílio erra."]'::jsonb, '[]'::jsonb, '["Art. 245"]'::jsonb, 'under_review', 'claude'
