insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não sendo encontrada a pessoa ou coisa procurada, os motivos da diligência serão comunicados a quem tiver sofrido a busca, se o requerer.', '["Busca infrutífera: comunicam-se os motivos a quem sofreu a busca, se requerer."]'::jsonb, '["Depende de requerimento."]'::jsonb, 'Nada foi encontrado, e o morador pede explicações sobre os motivos da diligência.', '["Assertiva que obriga a comunicação automática dos motivos da busca infrutífera erra: depende de requerimento."]'::jsonb, '[]'::jsonb, '["Art. 245"]'::jsonb, 'under_review', 'claude'
