insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A busca em mulher será feita por outra mulher, se não importar retardamento ou prejuízo da diligência.', '["Busca em mulher feita por outra mulher.","Exceção: se importar retardamento ou prejuízo da diligência."]'::jsonb, '["Exceção quando houver prejuízo à diligência."]'::jsonb, 'Policial feminina realiza a busca pessoal em suspeita do sexo feminino.', '["Assertiva que torna absoluta a regra de busca em mulher por outra mulher erra: há exceção."]'::jsonb, '[]'::jsonb, '["Art. 240, §2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-249'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autoridade ou seus agentes poderão penetrar no território de jurisdição alheia, ainda que de outro Estado, quando, para o fim de apreensão, forem no seguimento de pessoa ou coisa, devendo apresentar-se à competente autoridade local antes da diligência ou após, conforme a urgência. Entende-se que vão em seguimento quando, tendo conhecimento direto da remoção ou transporte, a seguirem sem interrupção, embora a percam de vista; ou, mesmo sem avistá-la, sabendo por informações fidedignas ou circunstâncias indiciárias que está sendo removida em determinada direção, forem ao seu encalço. As autoridades locais, havendo fundadas razões para duvidar da legitimidade das pessoas ou da legalidade dos mandados, poderão exigir as provas, mas sem frustrar a diligência.', '["Seguimento de pessoa ou coisa em outra jurisdição, mesmo de outro Estado.","Apresentação à autoridade local antes ou depois, conforme a urgência.","Seguimento: conhecimento direto e perseguição sem interrupção; ou informações fidedignas.","Autoridade local pode exigir provas de legitimidade, sem frustrar a diligência."]'::jsonb, '["Apresentação à autoridade local, antes ou depois, conforme a urgência."]'::jsonb, 'Policiais perseguem veículo com produto do crime para outro Estado e depois se apresentam à autoridade local.', '["Assertiva que exige sempre a apresentação prévia à autoridade local erra: pode ser depois, conforme a urgência."]'::jsonb, '[]'::jsonb, '["Art. 240"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-250'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao juiz incumbirá prover à regularidade do processo e manter a ordem no curso dos respectivos atos, podendo, para tal fim, requisitar a força pública.', '["Juiz zela pela regularidade do processo e pela ordem dos atos.","Pode requisitar a força pública."]'::jsonb, '["Poder de polícia do juiz nas audiências."]'::jsonb, 'O juiz requisita a força pública para manter a ordem na audiência.', '["Assertiva que impede o juiz de requisitar a força pública erra."]'::jsonb, '[]'::jsonb, '["Art. 252"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-251'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz não poderá exercer jurisdição no processo em que tiver funcionado seu cônjuge ou parente, consanguíneo ou afim, em linha reta ou colateral até o terceiro grau, inclusive, como defensor ou advogado, órgão do Ministério Público, autoridade policial, auxiliar da justiça ou perito; em que ele próprio houver desempenhado qualquer dessas funções ou servido como testemunha; em que tiver funcionado como juiz de outra instância, pronunciando-se de fato ou de direito sobre a questão; ou em que ele próprio, seu cônjuge ou parente, até o terceiro grau, for parte ou diretamente interessado.', '["I: cônjuge ou parente (até o terceiro grau) funcionou no processo como defensor, MP, autoridade policial, auxiliar ou perito.","II: o próprio juiz atuou em tais funções ou foi testemunha.","III: já decidiu a questão em outra instância.","IV: o juiz ou seus parentes são parte ou diretamente interessados."]'::jsonb, '["Hipóteses de IMPEDIMENTO (não de suspeição).","Rol taxativo segundo a doutrina majoritária."]'::jsonb, 'Juiz que já atuou no processo como membro do Ministério Público está impedido.', '["Assertiva que trata as hipóteses do art. 252 como suspeição erra: são casos de impedimento."]'::jsonb, '[{"termo":"Impedimento","significado":"Causa objetiva que proíbe o juiz de atuar no processo."}]'::jsonb, '["Art. 254","Art. 112"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-252'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos juízos coletivos, não poderão servir no mesmo processo os juízes que forem entre si parentes, consanguíneos ou afins, em linha reta ou colateral até o terceiro grau, inclusive.', '["Juízos coletivos: juízes parentes até o terceiro grau não atuam no mesmo processo."]'::jsonb, '["Impedimento por parentesco entre magistrados."]'::jsonb, 'Dois desembargadores primos-irmãos não integram a mesma turma no mesmo processo.', '["Assertiva que permite a atuação conjunta de juízes parentes em juízo coletivo erra."]'::jsonb, '[]'::jsonb, '["Art. 252"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-253'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz dar-se-á por suspeito, e, se não o fizer, poderá ser recusado por qualquer das partes: se for amigo íntimo ou inimigo capital de qualquer deles; se ele, seu cônjuge, ascendente ou descendente estiver respondendo a processo por fato análogo, sobre cujo caráter criminoso haja controvérsia; se ele, seu cônjuge ou parente até o terceiro grau sustentar demanda ou responder a processo que tenha de ser julgado por qualquer das partes; se tiver aconselhado qualquer das partes; se for credor ou devedor, tutor ou curador de qualquer das partes; ou se for sócio, acionista ou administrador de sociedade interessada no processo.', '["I: amigo íntimo ou inimigo capital.","II: ele ou parentes respondem a processo por fato análogo.","III: ele ou parentes têm demanda a ser julgada por qualquer das partes.","IV: aconselhou a parte.","V: credor, devedor, tutor ou curador.","VI: sócio, acionista ou administrador de sociedade interessada."]'::jsonb, '["Hipóteses de SUSPEIÇÃO (subjetivas), de rol discutido na doutrina."]'::jsonb, 'Juiz amigo íntimo do réu deve declarar-se suspeito.', '["Assertiva que classifica o juiz amigo íntimo da parte como caso de impedimento erra: é suspeição."]'::jsonb, '[{"termo":"Suspeição","significado":"Causa subjetiva que compromete a imparcialidade do juiz."}]'::jsonb, '["Art. 252","Art. 97"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-254'
