select u.id, u.content_sha256, 'Ao Ministério Público cabe promover, privativamente, a ação penal pública, na forma estabelecida no Código, e fiscalizar a execução da lei.', '["Promover, privativamente, a ação penal pública.","Fiscalizar a execução da lei."]'::jsonb, '["Privatividade da ação pública (Constituição, art. 129, I)."]'::jsonb, 'O MP oferece denúncia e atua como fiscal da lei.', '["Assertiva que torna a ação penal pública exclusiva da polícia erra."]'::jsonb, '[]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
