select u.id, u.content_sha256, 'Ao acusado menor dar-se-á curador. O dispositivo, anterior à maioridade civil aos 18 anos, está superado, pois o menor de 18 anos é inimputável.', '["Previa curador para o acusado menor.","Superado pela maioridade civil e penal aos 18 anos."]'::jsonb, '["Dispositivo histórico."]'::jsonb, 'Texto histórico, sem aplicação prática hoje.', '["Assertiva que exige curador para o acusado maior de 18 anos erra."]'::jsonb, '[]'::jsonb, '["Art. 15"]'::jsonb, 'under_review', 'claude'
