insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o acusado não tiver defensor, o juiz nomeará um, ressalvado o seu direito de, a todo tempo, nomear outro de sua confiança, ou a si mesmo defender-se, caso tenha habilitação. O acusado que não for pobre será obrigado a pagar os honorários do defensor dativo, arbitrados pelo juiz.', '["Acusado sem defensor: o juiz nomeia.","Pode nomear outro de confiança a qualquer tempo.","Pode defender-se a si mesmo, se habilitado.","Quem não é pobre paga os honorários do dativo."]'::jsonb, '["Defesa técnica obrigatória: a autodefesa é possível apenas por quem tem habilitação."]'::jsonb, 'Acusado sem advogado recebe defensor nomeado pelo juiz; se não é pobre, paga os honorários.', '["Assertiva que isenta o acusado não pobre do pagamento dos honorários do dativo erra."]'::jsonb, '[]'::jsonb, '["Art. 261"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-263'
