insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Salvo motivo relevante, os advogados e solicitadores serão obrigados, sob pena de multa de cem a quinhentos mil-réis, a prestar seu patrocínio aos acusados quando nomeados pelo juiz.', '["Advogados nomeados pelo juiz devem patrocinar o acusado.","Exceção: motivo relevante.","Sanção de multa (valores históricos)."]'::jsonb, '["Valores em moeda antiga; a lógica é o dever de patrocínio."]'::jsonb, 'Advogado nomeado dativo não pode recusar sem motivo relevante.', '["Assertiva que permite ao advogado nomeado recusar livremente o patrocínio erra."]'::jsonb, '[]'::jsonb, '["Art. 263"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-264'
