insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A constituição de defensor independerá de instrumento de mandato se o acusado o indicar por ocasião do interrogatório.', '["Defensor indicado pelo acusado no interrogatório dispensa procuração."]'::jsonb, '["Indicação feita no interrogatório."]'::jsonb, 'No interrogatório, o acusado indica seu advogado, que passa a atuar sem procuração.', '["Assertiva que exige procuração em qualquer hipótese de constituição de defensor erra."]'::jsonb, '[]'::jsonb, '["Art. 263"]'::jsonb, 'under_review', 'claude'
