insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As medidas cautelares do Título devem ser aplicadas observando-se a necessidade para aplicação da lei penal, para a investigação ou a instrução criminal e, nos casos expressamente previstos, para evitar a prática de infrações penais, e a adequação da medida à gravidade do crime, às circunstâncias do fato e às condições pessoais do indiciado ou acusado. Podem ser aplicadas isolada ou cumulativamente. São decretadas pelo juiz a requerimento das partes ou, no curso da investigação, por representação da autoridade policial ou mediante requerimento do Ministério Público. Ressalvados os casos de urgência ou perigo de ineficácia, o juiz, ao receber o pedido, determinará a intimação da parte contrária para se manifestar no prazo de 5 dias, acompanhada de cópia do requerimento e das peças necessárias.', '["Necessidade (aplicação da lei penal, investigação ou instrução, evitar novas infrações).","Adequação à gravidade do crime, circunstâncias do fato e condições pessoais.","Aplicação isolada ou cumulativa.","Decretação a requerimento das partes ou, na investigação, por representação policial ou requerimento do MP.","Contraditório prévio de 5 dias, salvo urgência ou perigo de ineficácia."]'::jsonb, '["Necessidade e adequação são requisitos CUMULATIVOS.","Contraditório prévio de 5 dias, salvo urgência.","O juiz não decreta cautelar de ofício na fase de investigação."]'::jsonb, 'Juiz aplica monitoramento eletrônico e proibição de contato, cumulando medidas adequadas ao caso.', '["Assertiva que permite ao juiz decretar medida cautelar de ofício na fase de investigação erra."]'::jsonb, '[]'::jsonb, '["Art. 283","Art. 312"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-282'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ninguém poderá ser preso senão em flagrante delito ou por ordem escrita e fundamentada da autoridade judiciária competente, em decorrência de prisão cautelar ou em virtude de condenação criminal transitada em julgado. As medidas cautelares do Título não se aplicam à infração a que não for isolada, cumulativa ou alternativamente cominada pena privativa de liberdade. A prisão poderá ser efetuada em qualquer dia e a qualquer hora, respeitadas as restrições relativas à inviolabilidade do domicílio.', '["Prisão só em flagrante ou por ordem escrita e fundamentada do juiz competente.","Hipóteses: prisão cautelar ou condenação transitada em julgado.","§1º: cautelares não se aplicam a infração sem pena privativa de liberdade.","§2º: prisão em qualquer dia e hora, respeitado o domicílio."]'::jsonb, '["A redação do caput (Lei nº 13.964, de 2019) exige trânsito em julgado para a prisão-pena; o STF decidiu sobre a execução provisória (ADCs 43, 44 e 54).","O domicílio protege a prisão noturna."]'::jsonb, 'Prisão preventiva decretada por juiz competente, por escrito e fundamentada.', '["Assertiva que permite a prisão por ordem não escrita da autoridade policial, fora do flagrante, erra."]'::jsonb, '[]'::jsonb, '["Art. 282","Art. 311"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-283'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

