insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autoridade que ordenar a prisão fará expedir o respectivo mandado. O mandado de prisão será lavrado pelo escrivão e assinado pela autoridade; designará a pessoa a ser presa por seu nome, alcunha ou sinais característicos; mencionará a infração penal que motivar a prisão; declarará o valor da fiança arbitrada, quando afiançável a infração; e será dirigido a quem tiver qualidade para dar-lhe execução.', '["Mandado lavrado pelo escrivão e assinado pela autoridade.","Designa a pessoa por nome, alcunha ou sinais.","Menciona a infração.","Declara o valor da fiança, se afiançável.","Dirigido a quem pode executá-lo."]'::jsonb, '["Requisitos formais do mandado."]'::jsonb, 'O mandado traz o nome do preso, a infração e o valor da fiança arbitrada.', '["Assertiva que dispensa a menção da infração no mandado de prisão erra."]'::jsonb, '[]'::jsonb, '["Art. 286"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-285'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O mandado será passado em duplicata, e o executor entregará ao preso, logo depois da prisão, um dos exemplares com declaração do dia, hora e lugar da diligência. Da entrega deverá o preso passar recibo no outro exemplar; se recusar, não souber ou não puder escrever, o fato será mencionado em declaração assinada por duas testemunhas.', '["Mandado em duplicata.","Entrega de um exemplar ao preso, com dia, hora e lugar.","Recibo no outro exemplar.","Recusa ou impossibilidade: declaração assinada por duas testemunhas."]'::jsonb, '["Duas testemunhas na recusa."]'::jsonb, 'O preso recebe uma via do mandado e assina recibo na outra.', '["Assertiva que dispensa a entrega de exemplar do mandado ao preso erra."]'::jsonb, '[]'::jsonb, '["Art. 285"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-286'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se a infração for inafiançável, a falta de exibição do mandado não obstará a prisão, e o preso, em tal caso, será imediatamente apresentado ao juiz que tiver expedido o mandado, para a realização de audiência de custódia.', '["Infração inafiançável: a falta de exibição do mandado não impede a prisão.","O preso é imediatamente apresentado ao juiz que expediu o mandado.","Realiza-se audiência de custódia."]'::jsonb, '["Só vale para infração INAFIANÇÁVEL."]'::jsonb, 'Em crime inafiançável, a prisão ocorre mesmo sem exibir o mandado no ato, com posterior apresentação ao juiz.', '["Assertiva que dispensa a audiência de custódia no caso do art. 287 erra."]'::jsonb, '[{"termo":"Audiência de custódia","significado":"Apresentação do preso ao juiz para controle da legalidade da prisão."}]'::jsonb, '["Art. 310"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-287'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ninguém será recolhido à prisão sem que seja exibido o mandado ao respectivo diretor ou carcereiro, a quem será entregue cópia assinada pelo executor ou apresentada a guia expedida pela autoridade competente, devendo ser passado recibo da entrega do preso, com declaração de dia e hora. O recibo poderá ser passado no próprio exemplar do mandado, se este for o documento exibido.', '["Recolhimento à prisão exige exibição do mandado ao diretor ou carcereiro.","Cópia assinada pelo executor ou guia expedida pela autoridade.","Recibo com dia e hora."]'::jsonb, '["Formalidades de recolhimento."]'::jsonb, 'O diretor da unidade recebe o mandado e passa recibo da entrega do preso.', '["Assertiva que dispensa recibo da entrega do preso ao diretor erra."]'::jsonb, '[]'::jsonb, '["Art. 285"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-288'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando o acusado estiver no território nacional, fora da jurisdição do juiz processante, será deprecada a sua prisão, devendo constar da precatória o inteiro teor do mandado. Havendo urgência, o juiz poderá requisitar a prisão por qualquer meio de comunicação, do qual deverá constar o motivo da prisão, bem como o valor da fiança, se arbitrada. A autoridade requisitada tomará as precauções necessárias para averiguar a autenticidade da comunicação. O juiz processante deverá providenciar a remoção do preso no prazo máximo de 30 dias, contados da efetivação da medida.', '["Acusado fora da jurisdição: prisão deprecada, com o teor do mandado.","Urgência: requisição por qualquer meio de comunicação.","Verificação da autenticidade pela autoridade requisitada.","Remoção do preso em até 30 dias."]'::jsonb, '["Prazo de 30 dias para a remoção do preso."]'::jsonb, 'O juiz requisita por telefone a prisão do acusado em outro Estado, por urgência.', '["Assertiva que fixa em 10 dias o prazo para a remoção do preso erra: são 30 dias."]'::jsonb, '[]'::jsonb, '["Art. 289-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-289'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz competente providenciará o imediato registro do mandado de prisão em banco de dados mantido pelo Conselho Nacional de Justiça. Qualquer agente policial poderá efetuar a prisão determinada no mandado registrado no CNJ, ainda que fora da competência territorial do juiz que o expediu. Poderá ainda efetuar a prisão decretada sem registro no CNJ, adotando as precauções para averiguar a autenticidade e comunicando ao juiz que a decretou, que providenciará o registro. A prisão será imediatamente comunicada ao juiz do local de cumprimento, que providenciará a certidão extraída do registro e informará o juízo que a decretou. O preso será informado de seus direitos, nos termos do inciso LXIII do art. 5º da Constituição, e, se não informar o nome de seu advogado, será comunicada a Defensoria Pública.', '["Registro imediato do mandado no banco de dados do CNJ.","Qualquer agente policial cumpre mandado registrado, mesmo fora do território do juiz.","Mandado não registrado: cumprimento com cautelas e comunicação ao juiz.","Comunicação ao juiz do local de cumprimento.","Preso informado de seus direitos; se não indicar advogado, comunica-se a Defensoria Pública."]'::jsonb, '["Registro no CNJ torna o mandado cumprível em todo o território."]'::jsonb, 'Policial de outro Estado cumpre mandado registrado no CNJ.', '["Assertiva que restringe o cumprimento do mandado ao território do juiz que o expediu erra, se registrado no CNJ."]'::jsonb, '[]'::jsonb, '["Art. 289"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-289-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o réu, sendo perseguido, passar ao território de outro município ou comarca, o executor poderá efetuar-lhe a prisão no lugar onde o alcançar, apresentando-o imediatamente à autoridade local, que, depois de lavrado, se for o caso, o auto de flagrante, providenciará a remoção do preso. Entende-se que o executor vai em perseguição quando, tendo-o avistado, for perseguindo-o sem interrupção, embora o tenha perdido de vista, ou quando, sabendo por indícios ou informações fidedignas que o réu passou há pouco em determinada direção, for no seu encalço. Se as autoridades locais tiverem fundadas razões para duvidar da legitimidade do executor ou da legalidade do mandado, poderão pôr em custódia o réu até esclarecida a dúvida.', '["Perseguição ao réu que passa para outro município ou comarca: prisão onde alcançar.","Apresentação imediata à autoridade local.","Perseguição: contínua após avistar, ou no encalço por indícios fidedignos.","Dúvida da autoridade local: custódia até esclarecer."]'::jsonb, '["Persecução (perseguição) contínua ou por indícios fidedignos."]'::jsonb, 'Policiais perseguem o réu, que cruza a divisa da comarca, e o prendem lá.', '["Assertiva que exige novo mandado ao cruzar a divisa da comarca durante a perseguição erra."]'::jsonb, '[]'::jsonb, '["Art. 250"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-290'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A prisão em virtude de mandado entender-se-á feita desde que o executor, fazendo-se conhecer do réu, lhe apresente o mandado e o intime a acompanhá-lo.', '["Prisão por mandado consuma-se quando o executor se identifica, apresenta o mandado e intima o réu a acompanhá-lo."]'::jsonb, '["Identificação, apresentação do mandado e intimação."]'::jsonb, 'O policial se identifica, mostra o mandado e intima o réu a acompanhá-lo.', '["Assertiva que dispensa a apresentação do mandado ao réu erra."]'::jsonb, '[]'::jsonb, '["Art. 285"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-291'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se houver, ainda que por parte de terceiros, resistência à prisão em flagrante ou à determinada por autoridade competente, o executor e as pessoas que o auxiliarem poderão usar dos meios necessários para defender-se ou para vencer a resistência, do que tudo se lavrará auto subscrito também por duas testemunhas. É vedado o uso de algemas em mulheres grávidas durante os atos médico-hospitalares preparatórios para o parto e durante o trabalho de parto, bem como em mulheres durante o período de puerpério imediato.', '["Resistência, mesmo de terceiros: uso dos meios necessários.","Auto subscrito por duas testemunhas.","Vedadas algemas em grávidas no parto e atos preparatórios e no puerpério imediato."]'::jsonb, '["Meios NECESSÁRIOS, com auto e duas testemunhas.","Vedação de algemas em gestante e parturiente."]'::jsonb, 'O policial vence a resistência com meios necessários e lavra auto com duas testemunhas.', '["Assertiva que autoriza o uso de algemas em mulher durante o trabalho de parto erra."]'::jsonb, '[]'::jsonb, '["Art. 284"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-292'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o executor do mandado verificar, com segurança, que o réu entrou ou se encontra em alguma casa, o morador será intimado a entregá-lo, à vista da ordem de prisão. Se não for obedecido imediatamente, o executor convocará duas testemunhas e, sendo dia, entrará à força na casa, arrombando as portas, se preciso; sendo noite, o executor, depois da intimação ao morador, se não for atendido, fará guardar todas as saídas, tornando a casa incomunicável, e, logo que amanheça, arrombará as portas e efetuará a prisão. O morador que se recusar a entregar o réu oculto em sua casa será levado à presença da autoridade para que se proceda contra ele como for de direito.', '["Réu em casa: intimação do morador a entregá-lo.","Sem obediência: duas testemunhas e entrada à força, de dia.","À noite: guardar as saídas e, ao amanhecer, arrombar as portas.","Morador que oculta o réu: conduzido à autoridade."]'::jsonb, '["A Constituição só permite a entrada sem consentimento, para cumprir ordem judicial, durante o DIA."]'::jsonb, 'À noite, o executor cerca a casa e espera amanhecer para entrar.', '["Assertiva que permite arrombar a casa à noite para cumprir o mandado de prisão erra."]'::jsonb, '[]'::jsonb, '["Art. 294","Art. 245"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-293'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No caso de prisão em flagrante, observar-se-á o disposto no artigo anterior, no que for aplicável.', '["Flagrante: aplica-se o art. 293, no que couber."]'::jsonb, '["No flagrante, o ingresso na casa é permitido a qualquer hora (Constituição, art. 5º, XI)."]'::jsonb, 'Flagrante dentro de casa permite a entrada sem mandado, respeitadas as regras constitucionais.', '["Assertiva que restringe a entrada em casa para flagrante ao período diurno erra à luz da Constituição."]'::jsonb, '[]'::jsonb, '["Art. 293"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-294'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Serão recolhidos a quartéis ou a prisão especial, à disposição da autoridade competente, quando sujeitos a prisão antes de condenação definitiva: os ministros de Estado; governadores, prefeito do Distrito Federal, seus secretários, prefeitos municipais, vereadores e chefes de Polícia; membros do Parlamento Nacional e das Assembleias Legislativas; os cidadãos inscritos no Livro de Mérito; oficiais das Forças Armadas e militares dos Estados e do Distrito Federal; os magistrados; os diplomados por faculdades superiores (objeto de ADPF); ministros de confissão religiosa; ministros do Tribunal de Contas; cidadãos que exerceram efetivamente a função de jurado; e delegados de polícia e guardas-civis, ativos e inativos.', '["Prisão especial antes de condenação definitiva para as categorias listadas.","Inclui ministros, governadores, parlamentares, magistrados, militares, jurados e delegados, entre outros.","Diplomados em curso superior: dispositivo questionado em ADPF."]'::jsonb, '["Vale só ANTES da condenação definitiva.","O STF considerou não recepcionado o privilégio dos diplomados em curso superior (ADPF 334)."]'::jsonb, 'Magistrado preso preventivamente cumpre a prisão em sala especial.', '["Assertiva que estende a prisão especial a quem já tem condenação definitiva erra."]'::jsonb, '[{"termo":"Prisão especial","significado":"Recolhimento em local distinto da prisão comum, antes da condenação definitiva."}]'::jsonb, '["Art. 300"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-295'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os inferiores e praças de pré, onde for possível, serão recolhidos à prisão em estabelecimentos militares, de acordo com os respectivos regulamentos.', '["Inferiores e praças de pré (militares): prisão em estabelecimentos militares, quando possível."]'::jsonb, '["Terminologia militar antiga."]'::jsonb, 'Praça militar cumpre a prisão em estabelecimento militar, onde possível.', '["Assertiva que determina a prisão comum para todos os praças erra: onde possível, estabelecimentos militares."]'::jsonb, '[]'::jsonb, '["Art. 295"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-296'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para o cumprimento de mandado expedido pela autoridade judiciária, a autoridade policial poderá expedir tantos outros quantos necessários às diligências, devendo neles ser fielmente reproduzido o teor do mandado original.', '["Autoridade policial expede mandados auxiliares para cumprir o do juiz.","Reproduz fielmente o teor do mandado original."]'::jsonb, '["Mandados auxiliares reproduzem o original."]'::jsonb, 'O delegado expede cópias do mandado para diferentes equipes cumprirem a ordem.', '["Assertiva que autoriza a autoridade policial a alterar o conteúdo do mandado ao reproduzi-lo erra."]'::jsonb, '[]'::jsonb, '["Art. 285"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-297'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A captura poderá ser requisitada, à vista de mandado judicial, por qualquer meio de comunicação, tomadas pela autoridade a quem se fizer a requisição as precauções necessárias para averiguar a autenticidade desta.', '["Captura pode ser requisitada por qualquer meio de comunicação.","Exige mandado judicial.","A autoridade requisitada verifica a autenticidade."]'::jsonb, '["Autenticidade verificada."]'::jsonb, 'A prisão é requisitada por meio eletrônico, e a autoridade confirma a autenticidade.', '["Assertiva que dispensa a verificação de autenticidade da requisição de captura erra."]'::jsonb, '[]'::jsonb, '["Art. 289"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-299'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As pessoas presas provisoriamente ficarão separadas das que já estiverem definitivamente condenadas, nos termos da lei de execução penal. O militar preso em flagrante delito, após a lavratura dos procedimentos legais, será recolhido a quartel da instituição a que pertencer, onde ficará preso à disposição das autoridades competentes.', '["Presos provisórios separados dos condenados definitivos.","Militar preso em flagrante: recolhido a quartel da própria instituição."]'::jsonb, '["Separação entre provisórios e definitivos."]'::jsonb, 'Preso preventivo e condenado definitivo ficam em alas diferentes.', '["Assertiva que permite manter juntos presos provisórios e condenados definitivos erra."]'::jsonb, '[]'::jsonb, '["Art. 295"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-300'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O investigado por crimes contra a dignidade sexual, quando preso cautelarmente, e o condenado pelos mesmos crimes deverão ser submetidos obrigatoriamente à identificação do perfil genético, mediante extração de DNA, por técnica adequada e indolor, por ocasião do ingresso no estabelecimento prisional.', '["Investigado preso cautelarmente por crime contra a dignidade sexual e condenado pelos mesmos crimes.","Identificação obrigatória do perfil genético (DNA).","Técnica adequada e indolor, no ingresso no estabelecimento prisional."]'::jsonb, '["Incluído pela Lei nº 15.280, de 2025."]'::jsonb, 'Ao ingressar no presídio, o preso por estupro tem o DNA coletado.', '["Assertiva que torna facultativa a coleta de DNA do art. 300-A erra: é obrigatória."]'::jsonb, '[]'::jsonb, '["Art. 9º-A da Lei de Execução Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-300-a'
