on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o réu se livrar solto, deverá ser posto em liberdade depois de lavrado o auto de prisão em flagrante.', '["Réu que se livra solto é posto em liberdade após a lavratura do auto."]'::jsonb, '["Relaciona-se à liberdade provisória e à fiança."]'::jsonb, 'Em infração em que se livra solto, o autuado é liberado após o auto.', '["Assertiva que mantém preso quem se livra solto, após o auto, erra."]'::jsonb, '[]'::jsonb, '["Art. 321"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-309'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Após receber o auto de prisão em flagrante, no prazo máximo de até 24 horas após a prisão, o juiz deverá promover, por videoconferência em tempo real, audiência de custódia com a presença do acusado, seu advogado constituído ou membro da Defensoria Pública e o membro do Ministério Público, e, nessa audiência, deverá, fundamentadamente: relaxar a prisão ilegal; converter a prisão em flagrante em preventiva, quando presentes os requisitos do art. 312 e se revelarem inadequadas ou insuficientes as medidas cautelares diversas da prisão; ou conceder liberdade provisória, com ou sem fiança. Se o juiz verificar, pelo auto, que o agente praticou o fato nas condições do art. 23, I, II ou III, do Código Penal (excludentes de ilicitude), poderá, fundamentadamente, conceder liberdade provisória mediante termo de comparecimento obrigatório. O texto vigente tem outros parágrafos sobre vedações e consequências da falta de audiência.', '["Audiência de custódia em até 24 horas da prisão, por videoconferência em tempo real.","Presenças: acusado, advogado ou Defensoria, Ministério Público.","Opções do juiz: relaxar a prisão ilegal; converter em preventiva; conceder liberdade provisória, com ou sem fiança.","§1º: excludentes de ilicitude do art. 23 do CP permitem liberdade provisória."]'::jsonb, '["Três caminhos fundamentados: relaxar, converter em preventiva ou conceder liberdade.","Prazo de até 24 horas após a prisão."]'::jsonb, 'Na audiência de custódia, o juiz relaxa a prisão por ilegalidade.', '["Assertiva que permite ao juiz manter a prisão em flagrante, sem converter em preventiva, erra: ele deve relaxar, converter ou conceder liberdade."]'::jsonb, '[]'::jsonb, '["Art. 287","Art. 312"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-310'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No caso de prisão em flagrante por crime praticado com violência ou grave ameaça contra a pessoa, por crime contra a dignidade sexual ou por crime praticado por agente integrante de organização criminosa armada, entre outras hipóteses do dispositivo, o juiz determinará a coleta de material biológico para obtenção do perfil genético. A coleta deverá ser feita, preferencialmente, na própria audiência de custódia ou no prazo de 10 dias, contado de sua realização. Será realizada por agente público treinado e respeitará os procedimentos de cadeia de custódia definidos pela legislação e complementados pelo órgão de perícia oficial de natureza criminal.', '["Prisão em flagrante por crime com violência ou grave ameaça, crime contra a dignidade sexual ou crime de integrante de organização criminosa armada, entre outras hipóteses.","Coleta de material biológico para o perfil genético.","Preferencialmente na audiência de custódia ou em até 10 dias.","Agente público treinado e cadeia de custódia."]'::jsonb, '["Incluído pela Lei nº 15.272, de 2025.","Confira o texto integral do caput para as hipóteses completas."]'::jsonb, 'Preso em flagrante por crime violento tem o DNA coletado na audiência de custódia.', '["Assertiva que dispensa a observância da cadeia de custódia na coleta do material biológico erra."]'::jsonb, '[]'::jsonb, '["Art. 310","Art. 158-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-310-a'
