insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em qualquer fase da investigação policial ou do processo penal, caberá a prisão preventiva decretada pelo juiz, a requerimento do Ministério Público, do querelante ou do assistente, ou por representação da autoridade policial.', '["Preventiva cabe em qualquer fase da investigação ou do processo.","Decretada pelo juiz.","A requerimento do MP, querelante ou assistente, ou por representação policial."]'::jsonb, '["A Lei nº 13.964, de 2019, retirou a decretação de ofício pelo juiz."]'::jsonb, 'O delegado representa pela preventiva, e o juiz decide.', '["Assertiva que permite ao juiz decretar a preventiva de ofício erra, segundo a redação atual do art. 311."]'::jsonb, '[]'::jsonb, '["Art. 312"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-311'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A prisão preventiva poderá ser decretada como garantia da ordem pública, da ordem econômica, por conveniência da instrução criminal ou para assegurar a aplicação da lei penal, quando houver prova da existência do crime e indício suficiente de autoria e de perigo gerado pelo estado de liberdade do imputado. Também poderá ser decretada em caso de descumprimento de obrigações impostas por outras medidas cautelares. A decisão deve ser motivada e fundamentada em receio de perigo e na existência concreta de fatos novos ou contemporâneos que justifiquem a medida. Na aferição da periculosidade do agente, geradora de riscos à ordem pública, devem ser considerados o modus operandi (uso reiterado de violência ou grave ameaça, premeditação), a participação em organização criminosa e a natureza, quantidade e variedade de drogas, entre outros fatores.', '["Fundamentos: ordem pública, ordem econômica, conveniência da instrução, aplicação da lei penal.","Requisitos: prova da existência do crime, indício suficiente de autoria e perigo da liberdade (fumus commissi delicti e periculum libertatis).","§1º: descumprimento de outras cautelares.","§2º: motivação com fatos novos ou contemporâneos.","§3º: critérios de periculosidade (modus operandi, organização criminosa, drogas)."]'::jsonb, '["Prova do CRIME e INDÍCIO de AUTORIA (não prova de autoria).","Exige contemporaneidade dos fatos."]'::jsonb, 'Preventiva por risco concreto de fuga para garantir a aplicação da lei penal.', '["Assertiva que exige prova plena da autoria para a preventiva erra: basta indício suficiente."]'::jsonb, '[{"termo":"Periculum libertatis","significado":"Perigo gerado pela liberdade do imputado."}]'::jsonb, '["Art. 311","Art. 313","Art. 315"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-312'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos termos do art. 312, será admitida a decretação da prisão preventiva nos crimes dolosos punidos com pena privativa de liberdade máxima superior a 4 anos; se o agente tiver sido condenado por outro crime doloso, em sentença transitada em julgado, ressalvado o inciso I do art. 64 do Código Penal (período depurador); se o crime envolver violência doméstica e familiar contra a mulher, criança, adolescente, idoso, enfermo ou pessoa com deficiência, para garantir a execução das medidas protetivas de urgência; se o crime for cometido por integrante de organização criminosa ultraviolenta, grupo paramilitar ou milícia privada; e nos crimes contra a dignidade sexual praticados contra criança ou adolescente, entre outras hipóteses do dispositivo.', '["I: crimes dolosos com pena máxima superior a 4 anos.","II: reincidente em crime doloso, ressalvado o período depurador.","III: violência doméstica e familiar, para garantir medidas protetivas.","V: organização criminosa ultraviolenta, grupo paramilitar ou milícia.","VI: crimes contra a dignidade sexual de criança ou adolescente e outros listados."]'::jsonb, '["Pena máxima SUPERIOR a 4 anos (não ''igual ou superior'').","Inciso IV revogado."]'::jsonb, 'Crime doloso com pena máxima de 8 anos admite preventiva, se presentes os requisitos do art. 312.', '["Assertiva que admite a preventiva em crime culposo punido com pena máxima superior a 4 anos, pelo inciso I, erra: o inciso trata de crimes dolosos."]'::jsonb, '[]'::jsonb, '["Art. 312","Art. 314"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-313'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A prisão preventiva em nenhum caso será decretada se o juiz verificar, pelas provas constantes dos autos, ter o agente praticado o fato nas condições previstas nos incisos I, II e III do caput do art. 23 do Código Penal (estado de necessidade, legítima defesa e estrito cumprimento do dever legal ou exercício regular de direito).', '["Preventiva vedada se o fato foi praticado sob excludente de ilicitude (art. 23, I, II e III, do CP)."]'::jsonb, '["Vedação absoluta (''em nenhum caso'')."]'::jsonb, 'Juiz percebe, pelas provas, que houve legítima defesa e não decreta a preventiva.', '["Assertiva que permite a preventiva mesmo diante de excludente de ilicitude evidente erra."]'::jsonb, '[]'::jsonb, '["Art. 310, §1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-314'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A decisão que decretar, substituir ou denegar a prisão preventiva será sempre motivada e fundamentada. Na motivação da decretação da preventiva ou de qualquer outra cautelar, o juiz deverá indicar concretamente a existência de fatos novos ou contemporâneos que justifiquem a medida. Não se considera fundamentada qualquer decisão judicial, seja interlocutória, sentença ou acórdão, que se limite à indicação, reprodução ou paráfrase de ato normativo sem explicar sua relação com a causa; empregue conceitos jurídicos indeterminados sem explicar o motivo concreto de sua incidência; invoque motivos que se prestariam a justificar qualquer outra decisão; não enfrente todos os argumentos capazes de, em tese, infirmar a conclusão; ou se limite a invocar precedente ou enunciado de súmula sem identificar seus fundamentos determinantes nem demonstrar que o caso se ajusta a eles, entre outras hipóteses do dispositivo.', '["Decisão sobre preventiva sempre motivada e fundamentada.","Fatos novos ou contemporâneos indicados concretamente.","§2º: decisão genérica não é fundamentada (paráfrase de norma, conceitos indeterminados sem explicação, motivos genéricos, argumentos não enfrentados, precedente sem fundamentos determinantes)."]'::jsonb, '["§2º aplica-se a qualquer decisão judicial, não só à preventiva."]'::jsonb, 'Decisão que apenas repete a fórmula ''garantia da ordem pública'', sem fatos concretos, é considerada não fundamentada.', '["Assertiva que aceita decisão que apenas reproduz o texto da lei como fundamentada erra."]'::jsonb, '[]'::jsonb, '["Art. 312"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-315'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz poderá, de ofício ou a pedido das partes, revogar a prisão preventiva se, no correr da investigação ou do processo, verificar a falta de motivo para que ela subsista, bem como novamente decretá-la, se sobrevierem razões que a justifiquem. Decretada a prisão preventiva, o órgão emissor da decisão deverá revisar a necessidade de sua manutenção a cada 90 dias, mediante decisão fundamentada, de ofício, sob pena de tornar a prisão ilegal. O texto indica ADIs sobre o parágrafo único.', '["Revogação da preventiva se faltar motivo para sua manutenção.","Nova decretação se sobrevierem razões.","Revisão a cada 90 dias, de ofício, por decisão fundamentada.","A falta de revisão pode tornar a prisão ilegal."]'::jsonb, '["Revisão a cada 90 DIAS.","O STF decidiu que a inobservância dos 90 dias não gera revogação automática da prisão (ADI 6581)."]'::jsonb, 'O juiz revisa, a cada 90 dias, se subsistem os motivos da preventiva.', '["Assertiva que fixa a revisão da preventiva a cada 60 dias erra: são 90 dias."]'::jsonb, '[]'::jsonb, '["Art. 312"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-316'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A prisão domiciliar consiste no recolhimento do indiciado ou acusado em sua residência, só podendo dela ausentar-se com autorização judicial.', '["Recolhimento na residência.","Saída somente com autorização judicial."]'::jsonb, '["Não confundir com o recolhimento domiciliar noturno (art. 319, V)."]'::jsonb, 'O acusado fica recolhido em casa e só sai com autorização do juiz.', '["Assertiva que permite saída livre do acusado em prisão domiciliar erra."]'::jsonb, '[]'::jsonb, '["Art. 318"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-317'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Poderá o juiz substituir a prisão preventiva pela domiciliar quando o agente for maior de 80 anos; extremamente debilitado por motivo de doença grave; imprescindível aos cuidados especiais de pessoa menor de 6 anos de idade ou com deficiência; gestante; mulher com filho de até 12 anos de idade incompletos; ou homem, caso seja o único responsável pelos cuidados do filho de até 12 anos incompletos. Para a substituição, o juiz exigirá prova idônea dos requisitos.', '["Maior de 80 anos.","Extremamente debilitado por doença grave.","Imprescindível aos cuidados de pessoa menor de 6 anos ou com deficiência.","Gestante.","Mulher com filho até 12 anos incompletos.","Homem único responsável por filho até 12 anos incompletos.","Prova idônea dos requisitos."]'::jsonb, '["Hipóteses facultativas (''poderá''); o art. 318-A trata do caso obrigatório."]'::jsonb, 'Preso maior de 80 anos pode ter a preventiva substituída pela domiciliar.', '["Assertiva que fixa a idade de 70 anos para a domiciliar do art. 318, I, erra: são 80 anos."]'::jsonb, '[]'::jsonb, '["Art. 318-A","Art. 317"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-318'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A prisão preventiva imposta à mulher gestante ou que for mãe ou responsável por crianças ou pessoas com deficiência será substituída por prisão domiciliar, desde que não tenha cometido crime com violência ou grave ameaça a pessoa e não tenha cometido o crime contra seu filho ou dependente.', '["Gestante, mãe ou responsável por crianças ou pessoas com deficiência.","Substituição por domiciliar (regra).","Condições: sem crime com violência ou grave ameaça; sem crime contra filho ou dependente."]'::jsonb, '["A substituição é a regra, quando presentes os requisitos.","O HC coletivo 143.641 do STF fundamentou a mudança, com ressalvas excepcionais."]'::jsonb, 'Gestante presa por crime sem violência tem a preventiva substituída por domiciliar.', '["Assertiva que torna facultativa a substituição do art. 318-A, mesmo presentes os requisitos, erra."]'::jsonb, '[]'::jsonb, '["Art. 318"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-318-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A substituição de que tratam os arts. 318 e 318-A poderá ser efetuada sem prejuízo da aplicação concomitante das medidas alternativas previstas no art. 319 do Código.', '["A prisão domiciliar pode ser acompanhada das medidas cautelares do art. 319."]'::jsonb, '["Cumulação com medidas alternativas."]'::jsonb, 'Preventiva substituída por domiciliar com monitoração eletrônica.', '["Assertiva que veda a cumulação da domiciliar com medidas do art. 319 erra."]'::jsonb, '[]'::jsonb, '["Art. 319"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-318-b'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São medidas cautelares diversas da prisão: comparecimento periódico em juízo; proibição de acesso ou frequência a determinados lugares; proibição de manter contato com pessoa determinada; proibição de ausentar-se da comarca; recolhimento domiciliar no período noturno e nos dias de folga, quando o investigado ou acusado tenha residência e trabalho fixos; suspensão do exercício de função pública ou de atividade de natureza econômica ou financeira; internação provisória do acusado nas hipóteses de crimes praticados com violência ou grave ameaça, quando os peritos concluírem ser inimputável ou semi-imputável e houver risco de reiteração; fiança; e monitoração eletrônica.', '["I: comparecimento periódico em juízo.","II: proibição de acesso ou frequência a certos lugares.","III: proibição de contato com pessoa determinada.","IV: proibição de ausentar-se da comarca.","V: recolhimento domiciliar noturno e nos dias de folga.","VI: suspensão de função pública ou atividade econômica.","VII: internação provisória.","VIII: fiança.","IX: monitoração eletrônica."]'::jsonb, '["Rol de nove medidas.","A internação provisória depende de perícia e de risco de reiteração."]'::jsonb, 'Proibição de contato com a vítima somada a monitoração eletrônica.', '["Assertiva que inclui a prisão temporária entre as medidas cautelares diversas da prisão erra."]'::jsonb, '[]'::jsonb, '["Art. 282","Art. 320"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-319'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A proibição de ausentar-se do País será comunicada pelo juiz às autoridades encarregadas de fiscalizar as saídas do território nacional, intimando-se o indiciado ou acusado para entregar o passaporte, no prazo de 24 horas.', '["Proibição de sair do País: comunicação às autoridades de fiscalização das saídas.","Entrega do passaporte em 24 horas."]'::jsonb, '["Prazo de 24 horas."]'::jsonb, 'O acusado é intimado a entregar o passaporte em 24 horas.', '["Assertiva que fixa em 5 dias o prazo para entrega do passaporte erra: são 24 horas."]'::jsonb, '[]'::jsonb, '["Art. 319"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-320'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ausentes os requisitos que autorizam a decretação da prisão preventiva, o juiz deverá conceder liberdade provisória, impondo, se for o caso, as medidas cautelares previstas no art. 319 e observados os critérios do art. 282. Os incisos I e II estão revogados.', '["Ausentes os requisitos da preventiva: liberdade provisória.","Pode impor medidas do art. 319, observado o art. 282."]'::jsonb, '["Liberdade provisória é a regra quando faltam os requisitos da preventiva."]'::jsonb, 'Sem requisitos da preventiva, o juiz concede liberdade provisória com comparecimento periódico.', '["Assertiva que mantém a prisão sem requisitos da preventiva erra."]'::jsonb, '[]'::jsonb, '["Art. 312","Art. 319"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-321'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autoridade policial somente poderá conceder fiança nos casos de infração cuja pena privativa de liberdade máxima não seja superior a 4 anos. Nos demais casos, a fiança será requerida ao juiz, que decidirá em 48 horas.', '["Delegado concede fiança se a pena máxima não for superior a 4 anos.","Demais casos: pedido ao juiz, que decide em 48 horas."]'::jsonb, '["Pena MÁXIMA não superior a 4 anos.","Juiz decide em 48 horas."]'::jsonb, 'Em infração com pena máxima de 3 anos, o delegado pode arbitrar fiança.', '["Assertiva que atribui ao delegado a concessão de fiança para pena máxima de 6 anos erra."]'::jsonb, '[]'::jsonb, '["Art. 325"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-322'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não será concedida fiança nos crimes de racismo; nos crimes de tortura, tráfico ilícito de entorpecentes e drogas afins, terrorismo e nos definidos como crimes hediondos; e nos crimes cometidos por grupos armados, civis ou militares, contra a ordem constitucional e o Estado Democrático. Os incisos IV e V foram revogados.', '["Racismo.","Tortura, tráfico, terrorismo e crimes hediondos.","Crimes de grupos armados contra a ordem constitucional e o Estado Democrático."]'::jsonb, '["Rol de crimes inafiançáveis (veja também a Constituição, art. 5º, XLII, XLIII e XLIV)."]'::jsonb, 'Crime de racismo é inafiançável.', '["Assertiva que admite fiança em crime de tortura erra."]'::jsonb, '[]'::jsonb, '["Art. 324"]'::jsonb, 'under_review', 'claude'
