insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O valor da fiança será fixado pela autoridade que a conceder nos seguintes limites: de 1 a 100 salários mínimos, quando se tratar de infração cuja pena privativa de liberdade, no grau máximo, não for superior a 4 anos; e de 10 a 200 salários mínimos, quando o máximo da pena privativa de liberdade cominada for superior a 4 anos. Se assim recomendar a situação econômica do preso, a fiança poderá ser dispensada, reduzida até o máximo de 2/3 ou aumentada em até 1.000 vezes.', '["Pena máxima até 4 anos: 1 a 100 salários mínimos.","Pena máxima superior a 4 anos: 10 a 200 salários mínimos.","Dispensa, redução de até 2/3 ou aumento de até 1.000 vezes, conforme a situação econômica."]'::jsonb, '["Faixas de valor e possibilidade de ajuste pela situação econômica."]'::jsonb, 'Preso muito rico tem a fiança aumentada em até 1.000 vezes.', '["Assertiva que fixa o teto da redução da fiança em metade erra: pode ser reduzida até 2/3."]'::jsonb, '[]'::jsonb, '["Art. 322","Art. 326"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-325'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para determinar o valor da fiança, a autoridade terá em consideração a natureza da infração, as condições pessoais de fortuna e vida pregressa do acusado, as circunstâncias indicativas de sua periculosidade, bem como a importância provável das custas do processo, até final julgamento.', '["Natureza da infração.","Condições pessoais de fortuna e vida pregressa.","Circunstâncias indicativas de periculosidade.","Custas prováveis do processo."]'::jsonb, '["Critérios de fixação do valor."]'::jsonb, 'O delegado considera a situação econômica do preso ao fixar a fiança.', '["Assertiva que desconsidera as condições de fortuna do acusado ao fixar a fiança erra."]'::jsonb, '[]'::jsonb, '["Art. 325"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-326'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A fiança tomada por termo obrigará o afiançado a comparecer perante a autoridade, todas as vezes que for intimado para atos do inquérito e da instrução criminal e para o julgamento. Quando o réu não comparecer, a fiança será havida como quebrada.', '["Afiançado deve comparecer a todos os atos do inquérito, da instrução e do julgamento.","Não comparecimento: fiança quebrada."]'::jsonb, '["Obrigação de comparecimento."]'::jsonb, 'Afiançado falta à audiência sem justificativa: fiança quebrada.', '["Assertiva que dispensa o comparecimento do afiançado aos atos do inquérito erra."]'::jsonb, '[]'::jsonb, '["Art. 341"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-327'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O réu afiançado não poderá, sob pena de quebramento da fiança, mudar de residência sem prévia permissão da autoridade processante, ou ausentar-se por mais de 8 dias de sua residência sem comunicar àquela autoridade o lugar onde será encontrado.', '["Mudança de residência exige prévia permissão.","Ausência por mais de 8 dias exige comunicação do local."]'::jsonb, '["Prazo de 8 dias."]'::jsonb, 'Afiançado viaja por 10 dias sem comunicar onde estará: quebra de fiança.', '["Assertiva que fixa em 15 dias o limite de ausência sem comunicação erra: são 8 dias."]'::jsonb, '[]'::jsonb, '["Art. 341"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-328'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos juízos criminais e delegacias de polícia, haverá um livro especial, com termos de abertura e de encerramento, numerado e rubricado em todas as suas folhas pela autoridade, destinado especialmente aos termos de fiança. O termo será lavrado pelo escrivão e assinado pela autoridade e por quem prestar a fiança, e dele extrair-se-á certidão para juntar-se aos autos. O réu e quem prestar a fiança serão notificados pelo escrivão das obrigações e da sanção previstas nos arts. 327 e 328, o que constará dos autos.', '["Livro especial de termos de fiança, numerado e rubricado.","Termo lavrado pelo escrivão e assinado pela autoridade e por quem presta a fiança.","Certidão juntada aos autos.","Notificação das obrigações e sanções dos arts. 327 e 328."]'::jsonb, '["Formalidades do termo de fiança."]'::jsonb, 'O escrivão lavra o termo de fiança no livro especial.', '["Assertiva que dispensa a notificação do réu quanto às obrigações da fiança erra."]'::jsonb, '[]'::jsonb, '["Art. 327","Art. 328"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-329'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A fiança, que será sempre definitiva, consistirá em depósito de dinheiro, pedras, objetos ou metais preciosos, títulos da dívida pública, federal, estadual ou municipal, ou em hipoteca inscrita em primeiro lugar. A avaliação de imóvel, pedras, objetos ou metais preciosos será feita imediatamente por perito nomeado pela autoridade. Quando a fiança consistir em caução de títulos da dívida pública, o valor será determinado pela sua cotação em Bolsa, e, sendo nominativos, exigir-se-á prova de que estão livres de ônus.', '["Fiança sempre definitiva.","Modalidades: depósito de dinheiro, pedras, objetos ou metais preciosos, títulos da dívida pública, ou hipoteca em primeiro lugar.","Avaliação imediata por perito.","Títulos: cotação em Bolsa e prova de que estão livres de ônus."]'::jsonb, '["Fiança sempre DEFINITIVA."]'::jsonb, 'A fiança é prestada mediante depósito em dinheiro.', '["Assertiva que admite fiança provisória no art. 330 erra: ela é sempre definitiva."]'::jsonb, '[]'::jsonb, '["Art. 331"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-330'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O valor em que consistir a fiança será recolhido à repartição arrecadadora federal ou estadual, ou entregue ao depositário público, juntando-se aos autos os respectivos conhecimentos. Nos lugares em que o depósito não se puder fazer de pronto, o valor será entregue ao escrivão ou pessoa abonada, a critério da autoridade, e dentro de três dias dar-se-á ao valor o destino que lhe assina o artigo, o que tudo constará do termo de fiança.', '["Valor recolhido à repartição arrecadadora ou entregue ao depositário público.","Conhecimentos juntados aos autos.","Sem depósito imediato: entrega ao escrivão ou pessoa abonada e destinação em três dias."]'::jsonb, '["Prazo de três dias para a destinação."]'::jsonb, 'Em local sem banco, a fiança é entregue ao escrivão e depositada em três dias.', '["Assertiva que fixa em 10 dias o prazo para dar destino ao valor entregue ao escrivão erra: são três dias."]'::jsonb, '[]'::jsonb, '["Art. 330"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-331'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em caso de prisão em flagrante, será competente para conceder a fiança a autoridade que presidir ao respectivo auto e, em caso de prisão por mandado, o juiz que o houver expedido, ou a autoridade judiciária ou policial a quem tiver sido requisitada a prisão.', '["Flagrante: autoridade que preside o auto.","Prisão por mandado: juiz que o expediu, ou autoridade a quem foi requisitada a prisão."]'::jsonb, '["Competência para conceder a fiança."]'::jsonb, 'Delegado que preside o auto de flagrante pode conceder a fiança, nos limites da lei.', '["Assertiva que atribui ao Ministério Público a concessão da fiança erra."]'::jsonb, '[]'::jsonb, '["Art. 322"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-332'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

