insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em qualquer fase da investigação policial ou do processo penal, a pedido da autoridade policial, do Ministério Público ou da vítima, o juiz poderá determinar a proibição do autor de exercer atividades que envolvam contato direto com pessoa em situação de vulnerabilidade, quando houver prova da existência do crime, indício suficiente de autoria e perigo gerado pelo estado de liberdade do imputado.', '["Em qualquer fase da investigação ou do processo.","A pedido da autoridade policial, do MP ou da vítima.","Proibição de atividades que envolvam contato direto com pessoa vulnerável.","Requisitos: prova do crime, indício suficiente de autoria e perigo da liberdade."]'::jsonb, '["Mesmos requisitos centrais da preventiva (art. 312)."]'::jsonb, 'O juiz proíbe o investigado de trabalhar com crianças enquanto durar o processo.', '["Assertiva que dispensa prova da existência do crime e indício de autoria no art. 350-B erra."]'::jsonb, '[]'::jsonb, '["Art. 312","Art. 350-A"]'::jsonb, 'under_review', 'claude'
