insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O mandado de citação indicará o nome do juiz; o nome do querelante nas ações iniciadas por queixa; o nome do réu, ou, se desconhecido, seus sinais característicos; a residência do réu, se conhecida; o fim para que é feita a citação; o juízo e o lugar, o dia e a hora em que o réu deverá comparecer; e a subscrição do escrivão e a rubrica do juiz.', '["Juiz e querelante (se houver).","Nome ou sinais característicos do réu e residência.","Finalidade da citação.","Juízo, lugar, dia e hora do comparecimento.","Subscrição do escrivão e rubrica do juiz."]'::jsonb, '["Requisitos formais do mandado de citação."]'::jsonb, 'O mandado traz o dia e a hora do comparecimento e a rubrica do juiz.', '["Assertiva que dispensa a rubrica do juiz no mandado de citação erra."]'::jsonb, '[]'::jsonb, '["Art. 351"]'::jsonb, 'under_review', 'claude'
