insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A precatória indicará o juiz deprecado e o juiz deprecante; a sede da jurisdição de um e de outro; o fim para que é feita a citação, com todas as especificações; e o juízo do lugar, o dia e a hora em que o réu deverá comparecer.', '["Juiz deprecado e deprecante.","Sede da jurisdição de ambos.","Finalidade da citação.","Juízo, dia e hora do comparecimento."]'::jsonb, '["Requisitos da precatória de citação."]'::jsonb, 'A precatória informa o juízo, o dia e a hora do comparecimento do réu.', '["Assertiva que dispensa a indicação da finalidade da citação na precatória erra."]'::jsonb, '[]'::jsonb, '["Art. 353"]'::jsonb, 'under_review', 'claude'
