insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A precatória será devolvida ao juiz deprecante, independentemente de traslado, depois de lançado o ''cumpra-se'' e de feita a citação por mandado do juiz deprecado. Verificado que o réu se encontra em território sujeito à jurisdição de outro juiz, a este o juiz deprecado remeterá os autos para efetivação da diligência, desde que haja tempo. Certificado pelo oficial de justiça que o réu se oculta para não ser citado, a precatória será imediatamente devolvida, para o fim previsto no art. 362.', '["Devolução da precatória ao juiz deprecante, sem traslado, após o ''cumpra-se'' e a citação.","Réu em outra jurisdição: remessa ao juiz competente, se houver tempo.","Réu que se oculta: devolução imediata para citação com hora certa."]'::jsonb, '["Ocultação do réu leva à citação com hora certa (art. 362)."]'::jsonb, 'O oficial certifica que o réu se oculta, e a precatória volta para a citação com hora certa.', '["Assertiva que mantém a precatória no juízo deprecado após constatada a ocultação do réu erra."]'::jsonb, '[]'::jsonb, '["Art. 362"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-355'
