insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nas intimações dos acusados, das testemunhas e demais pessoas que devam tomar conhecimento de qualquer ato, será observado, no que for aplicável, o disposto sobre a citação. A intimação do defensor constituído, do advogado do querelante e do assistente far-se-á por publicação no órgão incumbido da publicidade dos atos judiciais, incluindo, sob pena de nulidade, o nome do acusado. Não havendo órgão de publicação, a intimação far-se-á pelo escrivão, por mandado, via postal com comprovante ou outro meio idôneo. A intimação pessoal pelo escrivão dispensa a publicação. A intimação do Ministério Público e do defensor nomeado será pessoal.', '["Intimações seguem, no que couber, as regras da citação.","Defensor constituído, advogado do querelante e assistente: publicação com o nome do acusado, sob pena de nulidade.","Sem órgão de publicação: escrivão, por mandado, correio ou outro meio idôneo.","MP e defensor nomeado: intimação pessoal."]'::jsonb, '["Intimação PESSOAL do MP e do defensor nomeado (dativo/público)."]'::jsonb, 'O defensor público é intimado pessoalmente; o advogado constituído, por publicação com o nome do acusado.', '["Assertiva que admite a intimação por publicação do defensor nomeado erra: deve ser pessoal."]'::jsonb, '[]'::jsonb, '["Art. 351"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-370'
