insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Adiada, por qualquer motivo, a instrução criminal, o juiz marcará desde logo, na presença das partes e testemunhas, dia e hora para seu prosseguimento, do que se lavrará termo nos autos.', '["Instrução adiada: o juiz marca desde logo novo dia e hora.","Presença das partes e testemunhas.","Termo nos autos."]'::jsonb, '["Evita nova intimação: todos saem intimados."]'::jsonb, 'A audiência é adiada, e o juiz já marca nova data na presença de todos.', '["Assertiva que exige nova intimação das partes após o adiamento marcado na presença delas erra."]'::jsonb, '[]'::jsonb, '["Art. 370"]'::jsonb, 'under_review', 'claude'
