insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Transitando em julgado a sentença condenatória, serão executadas somente as interdições nela aplicadas ou que derivarem da imposição da pena principal.', '["Após o trânsito: executam-se só as interdições aplicadas na sentença ou derivadas da pena principal."]'::jsonb, '["Interdições provisórias anteriores não se executam por si."]'::jsonb, 'Só a interdição fixada na sentença condenatória é executada.', '["Assertiva que executa todas as interdições provisórias após o trânsito erra."]'::jsonb, '[]'::jsonb, '["Art. 373"]'::jsonb, 'under_review', 'claude'
