insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A aplicação provisória de medida de segurança obedecerá ao disposto nos artigos anteriores, com modificações: o juiz poderá aplicá-la de ofício ou a requerimento do Ministério Público; poderá ser determinada ainda no curso do inquérito, mediante representação da autoridade policial; a aplicação, substituição ou revogação poderão ocorrer também na sentença absolutória; e decretada a medida, atender-se-á ao Título V do Livro IV.', '["Juiz aplica de ofício ou a requerimento do MP.","Possível no inquérito, por representação da autoridade policial.","Possível na sentença absolutória.","Execução segue o Título V do Livro IV."]'::jsonb, '["Medida de segurança provisória pode ser aplicada já no inquérito."]'::jsonb, 'No inquérito, a autoridade policial representa pela medida de segurança provisória.', '["Assertiva que veda a aplicação provisória de medida de segurança no inquérito erra."]'::jsonb, '[]'::jsonb, '["Art. 373"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-378'
