insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos crimes de ação pública, o juiz poderá proferir sentença condenatória, ainda que o Ministério Público tenha opinado pela absolvição, bem como reconhecer agravantes, embora nenhuma tenha sido alegada.', '["Juiz pode condenar mesmo com pedido de absolvição do MP.","Pode reconhecer agravantes não alegadas."]'::jsonb, '["Muito discutido à luz do sistema acusatório (art. 3º-A): parte da doutrina entende o dispositivo incompatível."]'::jsonb, 'O MP pede absolvição, mas o juiz condena com base na prova.', '["Assertiva que vincula o juiz ao pedido de absolvição do MP, conforme o texto do art. 385, erra."]'::jsonb, '[]'::jsonb, '["Art. 3º-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-385'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz absolverá o réu, mencionando a causa na parte dispositiva, desde que reconheça estar provada a inexistência do fato; não haver prova da existência do fato; não constituir o fato infração penal; estar provado que o réu não concorreu para a infração; não existir prova de ter o réu concorrido para a infração; existirem circunstâncias que excluam o crime ou isentem o réu de pena (arts. 20, 21, 22, 23, 26 e §1º do art. 28 do Código Penal), ou mesmo se houver fundada dúvida sobre sua existência; ou não existir prova suficiente para a condenação. Na sentença absolutória, o juiz mandará pôr o réu em liberdade, ordenará a cessação das medidas cautelares e provisoriamente aplicadas e aplicará medida de segurança, se cabível.', '["I: provada a inexistência do fato.","II: não há prova da existência do fato.","III: o fato não constitui infração penal.","IV: provado que o réu não concorreu.","V: não há prova de que o réu concorreu.","VI: excludentes de ilicitude ou culpabilidade, ou dúvida sobre elas.","VII: prova insuficiente para a condenação.","Parágrafo único: liberdade, cessação das cautelares e medida de segurança, se cabível."]'::jsonb, '["Inexistência do fato (I) e prova de que o réu não concorreu (IV) repercutem no cível; já a atipicidade (III) não impede a ação civil (art. 67, III).","Dúvida sobre excludente leva à absolvição (VI)."]'::jsonb, 'Provado que o fato não existiu, o juiz absolve com base no inciso I.', '["Assertiva que dispensa mencionar a causa da absolvição na parte dispositiva erra."]'::jsonb, '[]'::jsonb, '["Art. 65","Art. 66","Art. 67"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-386'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz, ao proferir sentença condenatória, mencionará as circunstâncias agravantes ou atenuantes do Código Penal; mencionará as outras circunstâncias apuradas e tudo o mais que deva ser levado em conta na aplicação da pena, nos termos dos arts. 59 e 60 do Código Penal; aplicará as penas de acordo com essas conclusões; fixará valor mínimo para reparação dos danos causados pela infração, considerando os prejuízos sofridos pelo ofendido; atenderá ao disposto sobre aplicação provisória de interdições de direitos e medidas de segurança; e determinará se a sentença deverá ser publicada na íntegra ou em resumo. O juiz decidirá, fundamentadamente, sobre a manutenção ou imposição de prisão preventiva ou outra medida cautelar, sem prejuízo da apelação. O tempo de prisão provisória, de prisão administrativa ou de internação, no Brasil ou no estrangeiro, será computado para fins de determinação do regime inicial de pena privativa de liberdade.', '["Agravantes, atenuantes e circunstâncias dos arts. 59 e 60 do CP.","Aplicação das penas.","IV: valor mínimo para reparação dos danos.","V: interdições de direitos e medidas de segurança provisórias.","VI: publicação da sentença.","§1º: decide sobre prisão preventiva ou cautelar.","§2º: detração para o regime inicial."]'::jsonb, '["O valor mínimo de reparação do dano depende de pedido e de contraditório sobre o tema.","Detração: o tempo de prisão provisória é computado para o regime inicial."]'::jsonb, 'A sentença fixa o valor mínimo de reparação à vítima.', '["Assertiva que dispensa a fixação do valor mínimo de reparação dos danos na sentença condenatória erra."]'::jsonb, '[{"termo":"Detração","significado":"Desconto do tempo de prisão provisória na pena."}]'::jsonb, '["Art. 63","Art. 381"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-387'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A sentença poderá ser datilografada e, neste caso, o juiz a rubricará em todas as folhas.', '["Sentença datilografada: rubrica do juiz em todas as folhas."]'::jsonb, '["Hoje a regra é o meio eletrônico."]'::jsonb, 'Texto histórico, adaptado hoje ao processo eletrônico.', '["Assertiva que dispensa a rubrica do juiz em todas as folhas da sentença datilografada erra."]'::jsonb, '[]'::jsonb, '["Art. 389"]'::jsonb, 'under_review', 'claude'
