insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A sentença será publicada em mão do escrivão, que lavrará nos autos o respectivo termo, registrando-a em livro especialmente destinado a esse fim.', '["Publicação da sentença em mão do escrivão.","Termo nos autos e registro em livro especial."]'::jsonb, '["Rito formal de publicação."]'::jsonb, 'O juiz entrega a sentença ao escrivão, que a registra.', '["Assertiva que dispensa o registro da sentença em livro próprio erra."]'::jsonb, '[]'::jsonb, '["Art. 390"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-389'
