insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O escrivão, dentro de três dias após a publicação, e sob pena de suspensão de cinco dias, dará conhecimento da sentença ao órgão do Ministério Público.', '["Escrivão comunica a sentença ao MP em três dias.","Pena de suspensão de cinco dias."]'::jsonb, '["Prazo de três dias."]'::jsonb, 'O escrivão dá ciência ao MP da sentença em três dias.', '["Assertiva que fixa em 10 dias o prazo do escrivão para dar ciência ao MP erra: são três dias."]'::jsonb, '[]'::jsonb, '["Art. 389"]'::jsonb, 'under_review', 'claude'
