insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O querelante ou o assistente será intimado da sentença, pessoalmente ou na pessoa de seu advogado. Se nenhum deles for encontrado no lugar da sede do juízo, a intimação será feita mediante edital com o prazo de 10 dias, afixado no lugar de costume.', '["Querelante ou assistente intimados pessoalmente ou na pessoa do advogado.","Se não encontrados: edital de 10 dias."]'::jsonb, '["Edital de 10 dias."]'::jsonb, 'Nem o assistente nem seu advogado são encontrados: intimação por edital de 10 dias.', '["Assertiva que fixa em 90 dias o prazo do edital para o querelante erra: são 10 dias."]'::jsonb, '[]'::jsonb, '["Art. 392"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-391'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A intimação da sentença será feita ao réu, pessoalmente, se estiver preso; ao réu, pessoalmente, ou ao defensor por ele constituído, quando se livrar solto ou, sendo afiançável a infração, tiver prestado fiança; ao defensor constituído pelo réu, se este, expedido o mandado de prisão, não tiver sido encontrado; e por edital nos demais casos em que o réu e o defensor não forem encontrados, conforme certidão do oficial de justiça. O prazo do edital será de 90 dias, se tiver sido imposta pena privativa de liberdade por tempo igual ou superior a um ano, e de 60 dias, nos outros casos. O prazo para apelação correrá após o término do fixado no edital, salvo se, no curso deste, for feita a intimação por outra forma.', '["Réu preso: pessoalmente.","Réu solto ou afiançado: ele ou o defensor constituído.","Mandado de prisão sem localização do réu: defensor constituído.","Demais casos de não localização: edital.","Prazo do edital: 90 dias (pena igual ou superior a um ano) ou 60 dias (demais casos).","Prazo de apelação corre após o fim do edital."]'::jsonb, '["Edital: 90 dias se a pena privativa de liberdade for igual ou superior a um ano; senão 60 dias."]'::jsonb, 'Condenado a um ano de reclusão e não localizado: edital de 90 dias.', '["Assertiva que fixa em 60 dias o edital para pena igual ou superior a um ano erra: são 90 dias."]'::jsonb, '[]'::jsonb, '["Art. 391"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-392'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O procedimento será comum ou especial. O comum será ordinário (crime com sanção máxima igual ou superior a 4 anos de pena privativa de liberdade), sumário (sanção máxima inferior a 4 anos) ou sumaríssimo (infrações de menor potencial ofensivo, na forma da lei). Aplica-se a todos os processos o procedimento comum, salvo disposições em contrário do Código ou de lei especial. Nos processos de competência do Tribunal do Júri, o procedimento observa os arts. 406 a 497. As disposições dos arts. 395 a 398 aplicam-se a todos os procedimentos penais de primeiro grau, ainda que não regulados no Código.', '["Procedimento comum (ordinário, sumário, sumaríssimo) ou especial.","Ordinário: pena máxima igual ou superior a 4 anos.","Sumário: pena máxima inferior a 4 anos.","Sumaríssimo: menor potencial ofensivo.","Júri: arts. 406 a 497.","Arts. 395 a 398 valem para todos os procedimentos de primeiro grau."]'::jsonb, '["Ordinário: IGUAL ou SUPERIOR a 4 anos; sumário: INFERIOR a 4 anos.","O critério é a pena MÁXIMA."]'::jsonb, 'Crime com pena máxima de 6 anos segue o rito ordinário.', '["Assertiva que fixa o rito sumário para crimes com pena máxima igual a 4 anos erra: igual a 4 anos é ordinário."]'::jsonb, '[]'::jsonb, '["Art. 395","Art. 406"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-394'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os processos que apurem a prática de crime hediondo ou violência contra a mulher terão prioridade de tramitação em todas as instâncias. Os processos que apurem violência contra a mulher independem do pagamento de custas, taxas ou despesas processuais, salvo má-fé. As isenções aplicam-se apenas à vítima e, em caso de morte, ao cônjuge, ascendente, descendente ou irmão, quando a estes couber o direito de representação, de queixa ou de prosseguir a ação.', '["Prioridade de tramitação: crime hediondo e violência contra a mulher, em todas as instâncias.","Violência contra a mulher: sem custas, salvo má-fé.","Isenção só para a vítima e, em caso de morte, para familiares legitimados."]'::jsonb, '["A isenção de custas não alcança o acusado."]'::jsonb, 'A vítima de violência doméstica não paga custas processuais.', '["Assertiva que estende a isenção de custas ao acusado erra: aplica-se à vítima e aos familiares legitimados."]'::jsonb, '[]'::jsonb, '["Art. 31"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-394-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A denúncia ou queixa será rejeitada quando for manifestamente inepta; quando faltar pressuposto processual ou condição para o exercício da ação penal; ou quando faltar justa causa para o exercício da ação penal. O parágrafo único está revogado.', '["I: denúncia ou queixa manifestamente inepta.","II: falta de pressuposto processual ou de condição da ação.","III: falta de justa causa."]'::jsonb, '["Rejeição liminar da peça acusatória: cabe recurso em sentido estrito (art. 581, I)."]'::jsonb, 'Denúncia que não descreve o fato criminoso é rejeitada por inépcia.', '["Assertiva que recebe a denúncia sem justa causa erra: ela deve ser rejeitada."]'::jsonb, '[{"termo":"Justa causa","significado":"Lastro probatório mínimo para a ação penal."}]'::jsonb, '["Art. 41","Art. 396"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-395'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos procedimentos ordinário e sumário, oferecida a denúncia ou queixa, o juiz, se não a rejeitar liminarmente, a receberá e ordenará a citação do acusado para responder à acusação, por escrito, no prazo de 10 dias. No caso de citação por edital, o prazo para a defesa começa a fluir a partir do comparecimento pessoal do acusado ou do defensor constituído.', '["Recebimento da denúncia e citação para resposta escrita em 10 dias.","Citação por edital: o prazo começa com o comparecimento do acusado ou do defensor constituído."]'::jsonb, '["Prazo de 10 dias.","Prazo contado da citação pessoal (ou do comparecimento, no edital)."]'::jsonb, 'O acusado é citado e tem 10 dias para apresentar a resposta à acusação.', '["Assertiva que fixa em 5 dias o prazo de resposta à acusação erra: são 10 dias."]'::jsonb, '[]'::jsonb, '["Art. 396-A","Art. 399"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-396'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na resposta, o acusado poderá arguir preliminares e alegar tudo o que interesse à sua defesa, oferecer documentos e justificações, especificar as provas pretendidas e arrolar testemunhas, qualificando-as e requerendo sua intimação, quando necessário. A exceção será processada em apartado. Não apresentada a resposta no prazo legal, ou se o acusado, citado, não constituir defensor, o juiz nomeará defensor para oferecê-la, concedendo-lhe vista dos autos por 10 dias.', '["Resposta à acusação: preliminares, defesa, documentos, provas e rol de testemunhas.","Exceções em apartado (arts. 95 a 112).","Sem resposta no prazo: defensor nomeado, com vista de 10 dias."]'::jsonb, '["A resposta é OBRIGATÓRIA; sem ela, o juiz nomeia defensor.","Momento de arrolar testemunhas da defesa (preclusão)."]'::jsonb, 'Na resposta, a defesa arrola testemunhas e junta documentos.', '["Assertiva que dispensa a apresentação da resposta, seguindo o processo sem defensor, erra."]'::jsonb, '[]'::jsonb, '["Art. 396","Art. 397"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-396-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Após o cumprimento do disposto no art. 396-A e parágrafos, o juiz deverá absolver sumariamente o acusado quando verificar a existência manifesta de causa excludente da ilicitude do fato; a existência manifesta de causa excludente da culpabilidade do agente, salvo inimputabilidade; que o fato narrado evidentemente não constitui crime; ou extinta a punibilidade do agente.', '["I: excludente de ilicitude manifesta.","II: excludente de culpabilidade manifesta, salvo inimputabilidade.","III: fato evidentemente atípico.","IV: extinção da punibilidade."]'::jsonb, '["Inimputabilidade não autoriza absolvição sumária (a absolvição seria imprópria)."]'::jsonb, 'Legítima defesa manifestamente demonstrada: absolvição sumária.', '["Assertiva que permite a absolvição sumária por inimputabilidade erra: a exceção do inciso II a afasta."]'::jsonb, '[]'::jsonb, '["Art. 396-A","Art. 415"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-397'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Recebida a denúncia ou queixa, o juiz designará dia e hora para a audiência, ordenando a intimação do acusado, de seu defensor, do Ministério Público e, se for o caso, do querelante e do assistente. O acusado preso será requisitado para comparecer ao interrogatório, devendo o poder público providenciar sua apresentação. O juiz que presidiu a instrução deverá proferir a sentença (identidade física do juiz).', '["Designação de audiência e intimação das partes.","Réu preso requisitado ao interrogatório.","§2º: o juiz que presidiu a instrução sentencia (identidade física do juiz)."]'::jsonb, '["Identidade física do juiz: prevista no §2º (com exceções admitidas pela jurisprudência)."]'::jsonb, 'O juiz que colheu toda a prova profere a sentença.', '["Assertiva que dispensa a intimação do assistente, se houver, para a audiência erra."]'::jsonb, '[]'::jsonb, '["Art. 400"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-399'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na audiência de instrução e julgamento, a ser realizada no prazo máximo de 60 dias, proceder-se-á à tomada de declarações do ofendido, à inquirição das testemunhas arroladas pela acusação e pela defesa, nesta ordem, ressalvado o disposto no art. 222, bem como aos esclarecimentos dos peritos, às acareações e ao reconhecimento de pessoas e coisas, interrogando-se, em seguida, o acusado e procedendo-se o debate. As provas serão produzidas numa só audiência, podendo o juiz indeferir as consideradas irrelevantes, impertinentes ou protelatórias. Os esclarecimentos dos peritos dependerão de prévio requerimento das partes.', '["Audiência no prazo máximo de 60 dias.","Ordem: ofendido, testemunhas da acusação, testemunhas da defesa, peritos, acareações, reconhecimentos, interrogatório, debates.","Provas em uma só audiência; indeferimento das irrelevantes, impertinentes ou protelatórias.","Esclarecimentos dos peritos dependem de requerimento prévio."]'::jsonb, '["Interrogatório por ÚLTIMO (STF fixou que vale para todos os ritos).","Prazo máximo de 60 dias para a audiência."]'::jsonb, 'O interrogatório do acusado ocorre ao final da instrução, antes dos debates.', '["Assertiva que coloca o interrogatório do acusado no início da audiência erra: ele ocorre ao final da produção da prova."]'::jsonb, '[]'::jsonb, '["Art. 396","Art. 399"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-400'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na audiência de instrução e julgamento, e em especial nas que apurem crimes contra a dignidade sexual, todas as partes e demais sujeitos processuais deverão zelar pela integridade física e psicológica da vítima, sob pena de responsabilização civil, penal e administrativa, cabendo ao juiz garantir o cumprimento do disposto, sendo vedadas a manifestação sobre circunstâncias ou elementos alheios aos fatos objeto de apuração nos autos e a utilização de linguagem, informações ou material que ofendam a dignidade da vítima ou de testemunhas.', '["Todos devem zelar pela integridade física e psicológica da vítima.","Responsabilidade civil, penal e administrativa.","Juiz garante o cumprimento.","Vedada manifestação sobre elementos alheios aos fatos.","Vedada linguagem ou material que ofenda a dignidade da vítima ou de testemunhas."]'::jsonb, '["Incluído pela Lei nº 14.245, de 2021 (Lei Mariana Ferrer)."]'::jsonb, 'O juiz impede a defesa de usar linguagem ofensiva contra a vítima.', '["Assertiva que restringe o art. 400-A aos crimes contra a dignidade sexual erra: aplica-se a toda audiência, em especial a esses crimes."]'::jsonb, '[]'::jsonb, '["Art. 400"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-400-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na instrução poderão ser inquiridas até 8 testemunhas arroladas pela acusação e 8 pela defesa. Nesse número não se compreendem as que não prestem compromisso e as referidas. A parte poderá desistir da inquirição de qualquer das testemunhas arroladas, ressalvado o disposto no art. 209.', '["Até 8 testemunhas para a acusação e 8 para a defesa.","Não entram no cômputo as que não prestam compromisso e as referidas.","A parte pode desistir de testemunha, ressalvado o art. 209."]'::jsonb, '["Rito ordinário: 8 testemunhas por parte.","Informantes e testemunhas referidas não contam."]'::jsonb, 'A defesa arrola 8 testemunhas, e informantes ouvidos não entram na conta.', '["Assertiva que limita a 5 as testemunhas por parte no rito ordinário erra: são 8."]'::jsonb, '[]'::jsonb, '["Art. 209","Art. 532"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-401'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Produzidas as provas, ao final da audiência, o Ministério Público, o querelante e o assistente e, a seguir, o acusado poderão requerer diligências cuja necessidade se origine de circunstâncias ou fatos apurados na instrução.', '["Ao final da audiência, as partes podem requerer diligências.","Ordem: MP, querelante e assistente, depois acusado.","Só diligências nascidas de circunstâncias ou fatos da instrução."]'::jsonb, '["Diligências decorrentes da instrução, e não para recomeçar a prova."]'::jsonb, 'Um fato novo surgiu no depoimento, e a defesa requer uma diligência.', '["Assertiva que permite requerer qualquer diligência, sem relação com a instrução, no art. 402, erra."]'::jsonb, '[]'::jsonb, '["Art. 403","Art. 404"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-402'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não havendo requerimento de diligências, ou sendo indeferido, serão oferecidas alegações finais orais por 20 minutos, respectivamente, pela acusação e pela defesa, prorrogáveis por mais 10, proferindo o juiz, a seguir, sentença. Havendo mais de um acusado, o tempo previsto para a defesa de cada um é individual. Ao assistente do MP, após a manifestação deste, serão concedidos 10 minutos, prorrogando-se por igual período o tempo da defesa. O juiz poderá, considerada a complexidade do caso ou o número de acusados, conceder às partes o prazo de 5 dias sucessivamente para a apresentação de memoriais, tendo então 10 dias para proferir a sentença.', '["Alegações finais orais: 20 minutos para a acusação e 20 para a defesa, prorrogáveis por mais 10.","Vários acusados: tempo individual.","Assistente: 10 minutos, com igual prorrogação para a defesa.","Memoriais em 5 dias sucessivos; sentença em 10 dias."]'::jsonb, '["Memoriais: 5 dias para cada parte, sentença em 10 dias."]'::jsonb, 'Caso complexo: o juiz concede memoriais em 5 dias e sentencia em 10.', '["Assertiva que fixa em 30 minutos o tempo básico das alegações finais orais erra: são 20 minutos, prorrogáveis por mais 10."]'::jsonb, '[]'::jsonb, '["Art. 404"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-403'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ordenada diligência considerada imprescindível, de ofício ou a requerimento da parte, a audiência será concluída sem as alegações finais. Realizada, em seguida, a diligência determinada, as partes apresentarão, no prazo sucessivo de 5 dias, suas alegações finais, por memorial, e, no prazo de 10 dias, o juiz proferirá a sentença.', '["Diligência imprescindível: audiência concluída sem alegações finais.","Realizada a diligência: memoriais sucessivos de 5 dias.","Sentença em 10 dias."]'::jsonb, '["Alegações por memorial, 5 dias sucessivos."]'::jsonb, 'Perícia imprescindível é ordenada, e as alegações finais vêm em memoriais depois dela.', '["Assertiva que mantém as alegações finais orais mesmo após diligência imprescindível erra."]'::jsonb, '[]'::jsonb, '["Art. 403"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-404'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Do ocorrido em audiência será lavrado termo em livro próprio, assinado pelo juiz e pelas partes, contendo breve resumo dos fatos relevantes nela ocorridos. Sempre que possível, o registro dos depoimentos do investigado, indiciado, ofendido e testemunhas será feito pelos meios ou recursos de gravação magnética, estenotipia, digital ou técnica similar, inclusive audiovisual, destinada a obter maior fidelidade das informações. No caso de registro audiovisual, será encaminhada às partes cópia do registro original, sem necessidade de transcrição.', '["Termo da audiência assinado pelo juiz e pelas partes, com breve resumo.","Depoimentos registrados, sempre que possível, por gravação ou meios audiovisuais.","Registro audiovisual: cópia às partes, sem transcrição."]'::jsonb, '["Registro audiovisual dispensa transcrição."]'::jsonb, 'Os depoimentos são gravados em vídeo, e as partes recebem cópia, sem transcrição.', '["Assertiva que exige transcrição integral do registro audiovisual dos depoimentos erra."]'::jsonb, '[]'::jsonb, '["Art. 216"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-405'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No procedimento do Júri, o juiz, ao receber a denúncia ou queixa, ordenará a citação do acusado para responder à acusação, por escrito, no prazo de 10 dias. O prazo será contado a partir do efetivo cumprimento do mandado ou do comparecimento, em juízo, do acusado ou de defensor constituído, no caso de citação inválida ou por edital. A acusação deverá arrolar testemunhas, até o máximo de 8, na denúncia ou queixa. Na resposta, o acusado poderá arguir preliminares, alegar tudo que interesse à sua defesa, oferecer documentos, especificar provas e arrolar testemunhas, até o máximo de 8.', '["Citação para resposta escrita em 10 dias.","Prazo conta do cumprimento do mandado ou do comparecimento (se inválida ou por edital).","Acusação arrola até 8 testemunhas na denúncia ou queixa.","Defesa arrola até 8 na resposta."]'::jsonb, '["Primeira fase do Júri (judicium accusationis): 8 testemunhas por parte."]'::jsonb, 'Na primeira fase do Júri, a defesa responde por escrito em 10 dias e arrola até 8 testemunhas.', '["Assertiva que limita a 5 testemunhas por parte na primeira fase do Júri erra: são 8 (5 é o limite do plenário)."]'::jsonb, '[{"termo":"Sumário da culpa","significado":"Primeira fase do Júri, até a pronúncia."}]'::jsonb, '["Art. 422"]'::jsonb, 'under_review', 'claude'
