insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na audiência de instrução do Júri, proceder-se-á à tomada de declarações do ofendido, se possível, à inquirição das testemunhas arroladas pela acusação e pela defesa, nesta ordem, bem como aos esclarecimentos dos peritos, às acareações e ao reconhecimento de pessoas e coisas, interrogando-se, em seguida, o acusado e procedendo-se o debate. Os esclarecimentos dos peritos dependerão de prévio requerimento e deferimento pelo juiz. As provas serão produzidas em uma só audiência. Encerrada a instrução, observar-se-á, se for o caso, o art. 384. As alegações serão orais, concedendo-se a palavra à acusação e à defesa pelo prazo de 20 minutos, prorrogáveis por mais 10. Havendo mais de 1 acusado, o tempo é individual. Ao assistente do MP serão concedidos 10 minutos, entre outras disposições do dispositivo.', '["Ordem da prova: ofendido, testemunhas (acusação e defesa), peritos, acareações, reconhecimentos, interrogatório, debate.","Peritos: esclarecimentos dependem de requerimento e deferimento.","Provas em uma só audiência.","Art. 384 se necessário (mutatio libelli).","Alegações orais: 20 minutos, prorrogáveis por mais 10.","Mais de um acusado: tempo individual."]'::jsonb, '["Mesmo desenho da audiência do rito ordinário.","Fecha com debate oral."]'::jsonb, 'Na primeira fase do Júri, o acusado é interrogado por último e as partes debatem oralmente.', '["Assertiva que fixa em 10 minutos o tempo básico das alegações orais na primeira fase do Júri erra: são 20, prorrogáveis por mais 10."]'::jsonb, '[]'::jsonb, '["Art. 400","Art. 384"]'::jsonb, 'under_review', 'claude'
