insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O procedimento da primeira fase do Júri será concluído no prazo máximo de 90 dias.', '["Prazo máximo de 90 dias para concluir a primeira fase."]'::jsonb, '["Prazo impróprio, mas parâmetro de duração razoável."]'::jsonb, 'A primeira fase do procedimento do Júri deve terminar em até 90 dias.', '["Assertiva que fixa em 60 dias o prazo máximo da primeira fase do Júri erra: são 90 dias."]'::jsonb, '[]'::jsonb, '["Art. 411"]'::jsonb, 'under_review', 'claude'
