insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz, fundamentadamente, pronunciará o acusado, se convencido da materialidade do fato e da existência de indícios suficientes de autoria ou de participação. A fundamentação da pronúncia limitar-se-á à indicação da materialidade do fato e da existência de indícios suficientes de autoria ou de participação, devendo o juiz declarar o dispositivo legal em que julgar incurso o acusado e especificar as circunstâncias qualificadoras e as causas de aumento de pena. Se o crime for afiançável, o juiz arbitrará o valor da fiança para a concessão ou manutenção da liberdade provisória. O juiz decidirá, motivadamente, sobre a manutenção, revogação ou substituição da prisão ou medida restritiva de liberdade anteriormente decretada e, tratando-se de acusado solto, sobre a necessidade da prisão ou das medidas do Título IX do Livro I.', '["Pronúncia: materialidade do fato e indícios suficientes de autoria ou participação.","Fundamentação limitada a esses pontos (sem juízo de mérito aprofundado).","Declara o dispositivo legal e especifica qualificadoras e causas de aumento.","Fiança, se afiançável.","Decide sobre prisão e medidas cautelares."]'::jsonb, '["Na pronúncia vale ''in dubio pro societate'' (indícios suficientes, e não prova plena).","Qualificadoras devem ser especificadas."]'::jsonb, 'O juiz pronuncia o acusado, apontando a materialidade e os indícios de autoria.', '["Assertiva que exige prova plena da autoria para a pronúncia erra: bastam indícios suficientes."]'::jsonb, '[{"termo":"Pronúncia","significado":"Decisão que envia o acusado a julgamento pelo Júri."}]'::jsonb, '["Art. 414","Art. 415"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-413'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não se convencendo da materialidade do fato ou da existência de indícios suficientes de autoria ou de participação, o juiz, fundamentadamente, impronunciará o acusado. Enquanto não ocorrer a extinção da punibilidade, poderá ser formulada nova denúncia ou queixa se houver prova nova.', '["Impronúncia: ausência de materialidade ou de indícios suficientes de autoria.","Nova denúncia possível com prova nova, enquanto não extinta a punibilidade."]'::jsonb, '["Impronúncia não faz coisa julgada material: pode haver nova denúncia com prova nova."]'::jsonb, 'Não há indício suficiente de autoria: o juiz impronuncia o acusado.', '["Assertiva que impede nova denúncia após a impronúncia, mesmo com prova nova, erra."]'::jsonb, '[]'::jsonb, '["Art. 413","Art. 416"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-414'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz, fundamentadamente, absolverá desde logo o acusado quando provada a inexistência do fato; provado não ser ele autor ou partícipe do fato; o fato não constituir infração penal; ou demonstrada causa de isenção de pena ou de exclusão do crime. Não se aplica o inciso IV ao caso de inimputabilidade do caput do art. 26 do Código Penal, salvo quando esta for a única tese defensiva.', '["I: inexistência do fato provada.","II: provado que não é autor ou partícipe.","III: fato não constitui infração penal.","IV: isenção de pena ou exclusão do crime demonstrada.","Parágrafo único: inimputabilidade só absolve sumariamente se for a única tese defensiva."]'::jsonb, '["Absolvição sumária no Júri (diferente da impronúncia).","Inimputabilidade é exceção, salvo se for a única tese."]'::jsonb, 'Provado que o acusado não foi o autor, o juiz o absolve sumariamente.', '["Assertiva que sempre permite a absolvição sumária por inimputabilidade erra, ela só cabe se for a única tese defensiva."]'::jsonb, '[]'::jsonb, '["Art. 397","Art. 416"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-415'
