insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz poderá dar ao fato definição jurídica diversa da constante da acusação, embora o acusado fique sujeito a pena mais grave.', '["Na pronúncia, o juiz pode alterar a definição jurídica do fato.","Ainda que implique pena mais grave."]'::jsonb, '["Emendatio libelli na pronúncia."]'::jsonb, 'O juiz pronuncia o acusado por homicídio qualificado quando a denúncia o capitulava como simples, sem alterar os fatos.', '["Assertiva que proíbe a pronúncia com definição jurídica diversa e pena mais grave erra."]'::jsonb, '[]'::jsonb, '["Art. 383"]'::jsonb, 'under_review', 'claude'
