insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando o juiz se convencer, em discordância com a acusação, da existência de crime diverso dos referidos no §1º do art. 74 e não for competente para o julgamento, remeterá os autos ao juiz que o seja. Remetidos os autos a outro juiz, à disposição deste ficará o acusado preso.', '["Crime diverso dos dolosos contra a vida: remessa ao juiz competente.","Acusado preso fica à disposição do novo juiz."]'::jsonb, '["Desclassificação na primeira fase."]'::jsonb, 'O juiz entende que o crime não é doloso contra a vida e remete os autos ao juízo competente.', '["Assertiva que mantém o processo no juízo do Júri após a desclassificação erra."]'::jsonb, '[]'::jsonb, '["Art. 74"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-419'
