insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A intimação da decisão de pronúncia será feita pessoalmente ao acusado, ao defensor nomeado e ao Ministério Público; ao defensor constituído, ao querelante e ao assistente do MP, na forma do §1º do art. 370. Será intimado por edital o acusado solto que não for encontrado.', '["Intimação pessoal: acusado, defensor nomeado e MP.","Defensor constituído, querelante e assistente: por publicação (art. 370, §1º).","Acusado solto não encontrado: edital."]'::jsonb, '["Edital só para acusado SOLTO."]'::jsonb, 'O acusado preso é intimado pessoalmente da pronúncia.', '["Assertiva que admite a intimação por edital do acusado preso, da pronúncia, erra."]'::jsonb, '[]'::jsonb, '["Art. 370"]'::jsonb, 'under_review', 'claude'
