insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao receber os autos, o presidente do Tribunal do Júri determinará a intimação do Ministério Público ou do querelante, no caso de queixa, e do defensor, para, no prazo de 5 dias, apresentarem rol de testemunhas que irão depor em plenário, até o máximo de 5, oportunidade em que poderão juntar documentos e requerer diligência.', '["Fase de preparação do plenário.","Prazo de 5 dias para o rol de testemunhas.","Máximo de 5 testemunhas em plenário.","Possibilidade de juntar documentos e requerer diligência."]'::jsonb, '["No plenário: até 5 testemunhas por parte (na primeira fase, até 8)."]'::jsonb, 'Preclusa a pronúncia, as partes têm 5 dias para apresentar o rol de até 5 testemunhas.', '["Assertiva que fixa em 8 testemunhas o limite do rol para o plenário erra: são 5."]'::jsonb, '[]'::jsonb, '["Art. 406","Art. 423"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-422'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deliberando sobre os requerimentos de provas a serem produzidas ou exibidas no plenário do júri, e adotadas as providências devidas, o juiz presidente ordenará as diligências necessárias para sanar qualquer nulidade ou esclarecer fato que interesse ao julgamento da causa, e fará relatório sucinto do processo, determinando sua inclusão em pauta da reunião do Tribunal do Júri.', '["Juiz presidente delibera sobre as provas requeridas.","Ordena diligências para sanar nulidades e esclarecer fatos.","Faz relatório sucinto e inclui o processo em pauta."]'::jsonb, '["Relatório sucinto, que será lido em plenário (art. 472)."]'::jsonb, 'O juiz presidente faz o relatório e inclui o processo na pauta da reunião.', '["Assertiva que dispensa o relatório sucinto do processo erra."]'::jsonb, '[]'::jsonb, '["Art. 422"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-423'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando a lei local de organização judiciária não atribuir ao presidente do Tribunal do Júri o preparo para julgamento, o juiz competente remeter-lhe-á os autos do processo preparado até 5 dias antes do sorteio a que se refere o art. 433. Deverão ser remetidos também os processos preparados até o encerramento da reunião, para a realização de julgamento.', '["Juiz do preparo remete os autos ao presidente do Júri até 5 dias antes do sorteio.","Remessa também dos processos preparados até o fim da reunião."]'::jsonb, '["Prazo de 5 dias antes do sorteio."]'::jsonb, 'O juiz do preparo remete os autos ao presidente do Júri 5 dias antes do sorteio.', '["Assertiva que fixa em 15 dias antes do sorteio o prazo de remessa erra: são 5 dias."]'::jsonb, '[]'::jsonb, '["Art. 433"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-424'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Anualmente, serão alistados pelo presidente do Tribunal do Júri de 800 a 1.500 jurados nas comarcas de mais de 1.000.000 de habitantes, de 300 a 700 nas comarcas de mais de 100.000 habitantes e de 80 a 400 nas comarcas de menor população. Nas comarcas onde for necessário, poderá ser aumentado o número de jurados e organizada lista de suplentes. O juiz presidente requisitará às autoridades locais, associações, entidades culturais, instituições de ensino, universidades, sindicatos, repartições públicas e outros núcleos comunitários a indicação de pessoas que reúnam as condições para exercer a função de jurado.', '["800 a 1.500 jurados em comarcas com mais de 1.000.000 de habitantes.","300 a 700 em comarcas com mais de 100.000 habitantes.","80 a 400 nas comarcas menores.","Possibilidade de aumentar o número e organizar suplentes.","Indicação de jurados por entidades da comunidade."]'::jsonb, '["Faixas conforme a população da comarca."]'::jsonb, 'Comarca com menos de 100.000 habitantes alista de 80 a 400 jurados.', '["Assertiva que fixa o alistamento de 800 a 1.500 jurados para comarcas de menor população erra."]'::jsonb, '[]'::jsonb, '["Art. 426"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-425'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A lista geral dos jurados, com indicação das respectivas profissões, será publicada pela imprensa até o dia 10 de outubro de cada ano e divulgada em editais afixados à porta do Tribunal do Júri. A lista poderá ser alterada, de ofício ou mediante reclamação de qualquer do povo ao juiz presidente até o dia 10 de novembro, data de sua publicação definitiva. Juntamente com a lista, serão transcritos os arts. 436 a 446. Os nomes e endereços dos alistados, em cartões iguais, após serem verificados na presença do Ministério Público, de advogado indicado pela OAB e de defensor indicado pelas Defensorias Públicas, permanecerão guardados em urna fechada a chave, sob responsabilidade do juiz presidente. O jurado que tiver integrado o Conselho de Sentença nos 12 meses que antecederem à publicação da lista geral fica dela excluído. Anualmente, a lista geral de jurados será, obrigatoriamente, completada.', '["Lista publicada até 10 de outubro.","Reclamações até 10 de novembro, data da publicação definitiva.","Transcrição dos arts. 436 a 446.","Cartões guardados em urna sob responsabilidade do juiz.","Excluído quem integrou o Conselho de Sentença nos 12 meses anteriores.","Lista completada anualmente."]'::jsonb, '["Datas: 10 de outubro (publicação) e 10 de novembro (definitiva).","Exclusão de quem serviu nos 12 meses anteriores."]'::jsonb, 'Qualquer pessoa pode reclamar contra a lista até 10 de novembro.', '["Assertiva que fixa em 10 de dezembro a publicação definitiva da lista de jurados erra: é 10 de novembro."]'::jsonb, '[]'::jsonb, '["Art. 425"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-426'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o interesse da ordem pública o reclamar ou houver dúvida sobre a imparcialidade do júri ou a segurança pessoal do acusado, o Tribunal, a requerimento do Ministério Público, do assistente, do querelante ou do acusado, ou mediante representação do juiz competente, poderá determinar o desaforamento do julgamento para outra comarca da mesma região, onde não existam aqueles motivos. O pedido será distribuído imediatamente e terá preferência de julgamento. Sendo relevantes os motivos, o relator poderá determinar, fundamentadamente, a suspensão do julgamento pelo júri. Será ouvido o juiz presidente, quando a medida não tiver sido por ele solicitada. Na pendência de recurso contra a pronúncia ou quando efetivado o julgamento, não se admitirá o desaforamento, salvo, nesta última hipótese, quanto a fato ocorrido durante ou após julgamento anulado.', '["Motivos: interesse da ordem pública, dúvida sobre a imparcialidade do júri ou sobre a segurança do acusado.","Competência: o Tribunal, a pedido de MP, assistente, querelante, acusado ou por representação do juiz.","Desaforamento para comarca da mesma região.","Preferência de julgamento e possível suspensão do júri.","Não cabe na pendência de recurso contra a pronúncia nem após o julgamento, salvo fato novo."]'::jsonb, '["Quem decide é o TRIBUNAL.","Mesma região, sem os mesmos motivos."]'::jsonb, 'Dúvida sobre a imparcialidade do júri local leva ao desaforamento para outra comarca da mesma região.', '["Assertiva que atribui ao juiz presidente a decisão sobre o desaforamento erra: decide o Tribunal."]'::jsonb, '[{"termo":"Desaforamento","significado":"Deslocamento do julgamento do Júri para outra comarca."}]'::jsonb, '["Art. 428"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-427'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O desaforamento também poderá ser determinado, em razão do comprovado excesso de serviço, ouvidos o juiz presidente e a parte contrária, se o julgamento não puder ser realizado no prazo de 6 meses, contado do trânsito em julgado da decisão de pronúncia. Para a contagem do prazo, não se computará o tempo de adiamentos, diligências ou incidentes de interesse da defesa. Não havendo excesso de serviço ou existência de processos aguardando julgamento em quantidade que ultrapasse a possibilidade de apreciação pelo Tribunal do Júri nas reuniões periódicas, o acusado poderá requerer ao Tribunal que determine a imediata realização do julgamento.', '["Desaforamento por excesso de serviço comprovado.","Prazo de 6 meses contado do trânsito em julgado da pronúncia.","Não conta o tempo de adiamentos e diligências de interesse da defesa.","Sem excesso de serviço: acusado pode requerer a imediata realização do julgamento."]'::jsonb, '["Prazo de 6 meses."]'::jsonb, 'O julgamento não é realizado em 6 meses por excesso comprovado de serviço: cabe desaforamento.', '["Assertiva que fixa em 1 ano o prazo para o desaforamento por excesso de serviço erra: são 6 meses."]'::jsonb, '[]'::jsonb, '["Art. 427"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-428'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Salvo motivo relevante que autorize alteração na ordem dos julgamentos, terão preferência os acusados presos; dentre os acusados presos, aqueles que estiverem há mais tempo na prisão; e, em igualdade de condições, os precedentemente pronunciados. Antes do dia designado para o primeiro julgamento da reunião periódica, será afixada na porta do edifício do Tribunal do Júri a lista dos processos a serem julgados. O juiz presidente reservará datas na mesma reunião periódica para a inclusão de processo que tiver o julgamento adiado.', '["Preferência: acusados presos.","Entre os presos, os há mais tempo na prisão.","Em igualdade, os pronunciados há mais tempo.","Lista afixada na porta do Tribunal do Júri.","Datas reservadas para processos adiados."]'::jsonb, '["Ordem de preferência: presos, presos há mais tempo, pronunciados há mais tempo."]'::jsonb, 'Réu preso há mais tempo é julgado antes dos demais.', '["Assertiva que dá preferência ao acusado solto erra."]'::jsonb, '[]'::jsonb, '["Art. 431"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-429'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O assistente somente será admitido se tiver requerido sua habilitação até 5 dias antes da data da sessão na qual pretenda atuar.', '["Assistente deve requerer habilitação até 5 dias antes da sessão em que pretenda atuar."]'::jsonb, '["Prazo de 5 dias antes da sessão."]'::jsonb, 'A vítima se habilita como assistente 5 dias antes do plenário.', '["Assertiva que permite a habilitação do assistente no dia do julgamento no plenário erra."]'::jsonb, '[]'::jsonb, '["Art. 268"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-430'
