insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Estando o processo em ordem, o juiz presidente mandará intimar as partes, o ofendido, se for possível, as testemunhas e os peritos, quando houver requerimento, para a sessão de instrução e julgamento, observando, no que couber, o disposto no art. 420.', '["Intimação das partes, do ofendido (se possível), testemunhas e peritos (se requeridos).","Observa o art. 420 no que couber."]'::jsonb, '["Peritos só quando houver requerimento."]'::jsonb, 'O juiz presidente intima as partes e testemunhas para a sessão do Júri.', '["Assertiva que dispensa a intimação das partes para a sessão de julgamento erra."]'::jsonb, '[]'::jsonb, '["Art. 420"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-431'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em seguida à organização da pauta, o juiz presidente determinará a intimação do Ministério Público, da Ordem dos Advogados do Brasil e da Defensoria Pública para acompanharem, em dia e hora designados, o sorteio dos jurados que atuarão na reunião periódica.', '["Intimação do MP, da OAB e da Defensoria Pública para acompanhar o sorteio dos jurados."]'::jsonb, '["Fiscalização do sorteio por MP, OAB e Defensoria."]'::jsonb, 'OAB e Defensoria acompanham o sorteio dos jurados da reunião.', '["Assertiva que restringe o acompanhamento do sorteio ao Ministério Público erra."]'::jsonb, '[]'::jsonb, '["Art. 433"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-432'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O sorteio, presidido pelo juiz, far-se-á a portas abertas, cabendo-lhe retirar as cédulas até completar o número de 25 jurados, para a reunião periódica ou extraordinária. O sorteio será realizado entre o 15º e o 10º dia útil antecedente à instalação da reunião. A audiência de sorteio não será adiada pelo não comparecimento das partes. O jurado não sorteado poderá ter o seu nome novamente incluído para as reuniões futuras.', '["Sorteio público, presidido pelo juiz.","25 jurados por reunião.","Entre o 15º e o 10º dia útil antes da reunião.","Não é adiado pela ausência das partes.","Jurado não sorteado pode ser incluído em reuniões futuras."]'::jsonb, '["25 jurados.","Do 15º ao 10º dia útil antes."]'::jsonb, 'O juiz sorteia, a portas abertas, 25 jurados para a reunião.', '["Assertiva que fixa em 21 o número de jurados sorteados para a reunião erra: são 25."]'::jsonb, '[]'::jsonb, '["Art. 432","Art. 434"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-433'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os jurados sorteados serão convocados pelo correio ou por qualquer outro meio hábil para comparecer no dia e hora designados para a reunião, sob as penas da lei. No mesmo expediente de convocação serão transcritos os arts. 436 a 446 do Código.', '["Convocação por correio ou outro meio hábil.","Sob as penas da lei.","Transcrição dos arts. 436 a 446."]'::jsonb, '["A convocação traz os deveres e as sanções."]'::jsonb, 'Os jurados recebem convocação com a transcrição dos arts. 436 a 446.', '["Assertiva que dispensa a transcrição dos arts. 436 a 446 na convocação erra."]'::jsonb, '[]'::jsonb, '["Art. 433","Art. 436"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-434'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Serão afixados na porta do edifício do Tribunal do Júri a relação dos jurados convocados, os nomes do acusado e dos procuradores das partes, além do dia, hora e local das sessões de instrução e julgamento.', '["Afixação na porta do Tribunal do Júri: jurados convocados, acusado, procuradores, dia, hora e local."]'::jsonb, '["Publicidade da pauta e dos jurados convocados."]'::jsonb, 'A porta do fórum exibe a lista dos jurados e os dados da sessão.', '["Assertiva que mantém sigilo da relação dos jurados convocados erra: ela é afixada."]'::jsonb, '[]'::jsonb, '["Art. 434"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-435'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O serviço do júri é obrigatório. O alistamento compreenderá os cidadãos maiores de 18 anos de notória idoneidade. Nenhum cidadão poderá ser excluído dos trabalhos do júri ou deixar de ser alistado em razão de cor ou etnia, raça, credo, sexo, profissão, classe social ou econômica, origem ou grau de instrução. A recusa injustificada ao serviço do júri acarretará multa no valor de 1 a 10 salários mínimos, a critério do juiz, de acordo com a condição econômica do jurado.', '["Serviço do júri obrigatório.","Alistamento: maiores de 18 anos de notória idoneidade.","Vedada a exclusão por cor, etnia, raça, credo, sexo, profissão, classe social, origem ou instrução.","Recusa injustificada: multa de 1 a 10 salários mínimos."]'::jsonb, '["Multa de 1 a 10 salários mínimos.","Maioridade de 18 anos."]'::jsonb, 'Recusa injustificada ao serviço do júri gera multa.', '["Assertiva que torna facultativo o serviço do júri erra: é obrigatório."]'::jsonb, '[]'::jsonb, '["Art. 437"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-436'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Estão isentos do serviço do júri o Presidente da República e os Ministros de Estado; os Governadores e seus Secretários; os membros do Congresso Nacional, das Assembleias Legislativas e das Câmaras Distrital e Municipais; os Prefeitos Municipais; os Magistrados e membros do Ministério Público e da Defensoria Pública; os servidores do Judiciário, do Ministério Público e da Defensoria; as autoridades e servidores da polícia e da segurança pública; os militares em serviço ativo; os cidadãos maiores de 70 anos que requeiram sua dispensa; e aqueles que o requererem, demonstrando justo impedimento.', '["Isenção de agentes políticos, magistrados, MP, Defensoria, servidores, polícia e militares em serviço ativo.","Maiores de 70 anos: isenção se requererem.","Quem demonstrar justo impedimento."]'::jsonb, '["Maiores de 70 anos: dispensa a REQUERIMENTO."]'::jsonb, 'Cidadão de 72 anos requer a dispensa do serviço do júri.', '["Assertiva que isenta automaticamente os maiores de 70 anos, sem requerimento, erra."]'::jsonb, '[]'::jsonb, '["Art. 436"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-437'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A recusa ao serviço do júri fundada em convicção religiosa, filosófica ou política importará no dever de prestar serviço alternativo, sob pena de suspensão dos direitos políticos, enquanto não prestar o serviço imposto. Entende-se por serviço alternativo o exercício de atividades de caráter administrativo, assistencial, filantrópico ou mesmo produtivo, no Poder Judiciário, na Defensoria Pública, no Ministério Público ou em entidade conveniada. O juiz fixará o serviço alternativo atendendo aos princípios da proporcionalidade e da razoabilidade.', '["Escusa de consciência: serviço alternativo.","Sob pena de suspensão dos direitos políticos.","Serviço alternativo: atividades administrativas, assistenciais, filantrópicas ou produtivas.","Fixação com proporcionalidade e razoabilidade."]'::jsonb, '["Escusa de consciência gera serviço alternativo."]'::jsonb, 'Jurado que recusa por convicção religiosa presta serviço alternativo definido pelo juiz.', '["Assertiva que isenta totalmente quem recusa por convicção religiosa erra: deve prestar serviço alternativo."]'::jsonb, '[]'::jsonb, '["Art. 436"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-438'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O exercício efetivo da função de jurado constituirá serviço público relevante e estabelecerá presunção de idoneidade moral.', '["Serviço público relevante.","Presunção de idoneidade moral."]'::jsonb, '["Exercício EFETIVO da função."]'::jsonb, 'O jurado que efetivamente atuou goza de presunção de idoneidade moral.', '["Assertiva que concede presunção de idoneidade a quem apenas foi alistado erra: exige exercício efetivo."]'::jsonb, '[]'::jsonb, '["Art. 440"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-439'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Constitui também direito do jurado, na condição do art. 439, preferência, em igualdade de condições, nas licitações públicas e no provimento, mediante concurso, de cargo ou função pública, bem como nos casos de promoção funcional ou remoção voluntária.', '["Preferência, em igualdade de condições, em licitações públicas.","Preferência em provimento por concurso, promoção funcional ou remoção voluntária."]'::jsonb, '["Preferência apenas em igualdade de condições."]'::jsonb, 'Em empate num concurso, o candidato que foi jurado tem preferência.', '["Assertiva que dá ao jurado preferência independentemente de igualdade de condições erra."]'::jsonb, '[]'::jsonb, '["Art. 439"]'::jsonb, 'under_review', 'claude'
