insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O julgamento não será adiado se a testemunha deixar de comparecer, salvo se uma das partes tiver requerido a sua intimação por mandado, na oportunidade do art. 422, declarando não prescindir do depoimento e indicando a sua localização. Se, intimada, a testemunha não comparecer, o juiz presidente suspenderá os trabalhos e mandará conduzi-la ou adiará o julgamento para o primeiro dia desimpedido, ordenando a sua condução. O julgamento será realizado mesmo na hipótese de a testemunha não ser encontrada no local indicado, se assim for certificado por oficial de justiça.', '["Regra: a ausência da testemunha não adia o julgamento.","Exceção: parte requereu intimação por mandado (art. 422), declarando não prescindir do depoimento e indicando a localização.","Intimada e ausente: condução imediata ou adiamento com condução.","Testemunha não encontrada, certificado pelo oficial: julgamento realizado."]'::jsonb, '["A cláusula ''não prescindir'' (art. 422) é essencial."]'::jsonb, 'A parte declarou não prescindir do depoimento e indicou o endereço; a testemunha faltou: condução ou adiamento.', '["Assertiva que adia sempre o julgamento pela ausência de qualquer testemunha erra."]'::jsonb, '[]'::jsonb, '["Art. 422"]'::jsonb, 'under_review', 'claude'
