insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Antes do sorteio dos membros do Conselho de Sentença, o juiz presidente esclarecerá sobre os impedimentos, a suspeição e as incompatibilidades constantes dos arts. 448 e 449. O juiz presidente também advertirá os jurados de que, uma vez sorteados, não poderão comunicar-se entre si e com outrem, nem manifestar sua opinião sobre o processo, sob pena de exclusão do Conselho e multa, na forma do §2º do art. 436. A incomunicabilidade será certificada nos autos pelo oficial de justiça.', '["Esclarecimento sobre impedimentos, suspeição e incompatibilidades (arts. 448 e 449).","Advertência de incomunicabilidade e proibição de opinar.","Sanção: exclusão do Conselho e multa.","Incomunicabilidade certificada pelo oficial de justiça."]'::jsonb, '["Incomunicabilidade dos jurados sorteados."]'::jsonb, 'O juiz adverte os jurados de que não podem comentar o caso entre si.', '["Assertiva que permite aos jurados sorteados conversar sobre o processo erra."]'::jsonb, '[]'::jsonb, '["Art. 448","Art. 449"]'::jsonb, 'under_review', 'claude'
