insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O registro dos depoimentos e do interrogatório será feito pelos meios ou recursos de gravação magnética, eletrônica, estenotipia ou técnica similar, destinada a obter maior fidelidade e celeridade na colheita da prova. A transcrição do registro, após feita a degravação, constará dos autos.', '["Registro por gravação magnética, eletrônica, estenotipia ou técnica similar.","Transcrição, após degravação, consta dos autos."]'::jsonb, '["Fidelidade e celeridade."]'::jsonb, 'Os depoimentos no plenário são gravados e degravados.', '["Assertiva que dispensa a transcrição do registro nos autos erra."]'::jsonb, '[]'::jsonb, '["Art. 405"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-475'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Encerrada a instrução, será concedida a palavra ao Ministério Público, que fará a acusação, nos limites da pronúncia ou das decisões posteriores que julgaram admissível a acusação, sustentando, se for o caso, a existência de circunstância agravante. O assistente falará depois do Ministério Público. Na ação penal privada, falará em primeiro lugar o querelante e, em seguida, o Ministério Público, salvo se este houver retomado a titularidade da ação. Finda a acusação, terá a palavra a defesa. A acusação poderá replicar e a defesa treplicar, sendo admitida a reinquirição de testemunha já ouvida em plenário.', '["Acusação pelo MP nos limites da pronúncia.","Assistente depois do MP.","Ação privada: querelante primeiro.","Defesa após a acusação.","Réplica e tréplica, com reinquirição possível."]'::jsonb, '["Acusação limitada pela PRONÚNCIA."]'::jsonb, 'O MP sustenta a acusação nos limites da pronúncia e a defesa responde em seguida.', '["Assertiva que permite ao MP ampliar a acusação além dos limites da pronúncia erra."]'::jsonb, '[]'::jsonb, '["Art. 477"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-476'
