insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não havendo dúvida a ser esclarecida, o juiz presidente, os jurados, o Ministério Público, o assistente, o querelante, o defensor do acusado, o escrivão e o oficial de justiça dirigir-se-ão à sala especial a fim de ser procedida a votação. Na falta de sala especial, o juiz presidente determinará que o público se retire, permanecendo somente as pessoas mencionadas. O juiz presidente advertirá as partes de que não será permitida qualquer intervenção que possa perturbar a livre manifestação do Conselho e fará retirar da sala quem se portar inconvenientemente.', '["Votação em sala especial, com presentes limitados.","Sem sala especial: público se retira.","Proibida intervenção que perturbe a livre manifestação do Conselho."]'::jsonb, '["Sigilo da votação, mas com a presença de partes e escrivão."]'::jsonb, 'Sem sala especial, o público é retirado e a votação ocorre no plenário.', '["Assertiva que permite a presença do público na votação, na falta de sala especial, erra."]'::jsonb, '[{"termo":"Sala especial","significado":"Local da votação dos quesitos, com acesso restrito."}]'::jsonb, '["Art. 486"]'::jsonb, 'under_review', 'claude'
