select u.id, u.content_sha256, 'Para assegurar o sigilo do voto, o oficial de justiça recolherá em urnas separadas as cédulas correspondentes aos votos e as não utilizadas.', '["Urnas separadas para as cédulas votadas e para as não utilizadas."]'::jsonb, '["Mantém o sigilo do voto, evitando identificar a votação."]'::jsonb, 'Voto e cédulas restantes vão para urnas diferentes.', '["Assertiva que recolhe em uma só urna os votos e as cédulas não utilizadas erra."]'::jsonb, '[]'::jsonb, '["Art. 486"]'::jsonb, 'under_review', 'claude'
