insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Após a resposta, verificados os votos e as cédulas não utilizadas, o presidente determinará que o escrivão registre no termo a votação de cada quesito, bem como o resultado do julgamento. Do termo também constará a conferência das cédulas não utilizadas.', '["Verificação dos votos e das cédulas não utilizadas.","Registro no termo da votação de cada quesito e do resultado.","Conferência das cédulas não utilizadas consta do termo."]'::jsonb, '["A apuração é interrompida quando se alcança maioria (sigilo da unanimidade)."]'::jsonb, 'O escrivão registra no termo o resultado de cada quesito.', '["Assertiva que dispensa a conferência das cédulas não utilizadas erra."]'::jsonb, '[]'::jsonb, '["Art. 491"]'::jsonb, 'under_review', 'claude'
