insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se a resposta a qualquer dos quesitos estiver em contradição com outra ou outras já dadas, o presidente, explicando aos jurados em que consiste a contradição, submeterá novamente à votação os quesitos a que se referirem tais respostas. Se, pela resposta dada a um dos quesitos, o presidente verificar que ficam prejudicados os seguintes, assim o declarará, dando por finda a votação.', '["Respostas contraditórias: o presidente explica a contradição e submete novamente a votação.","Quesitos prejudicados: o presidente declara e encerra a votação."]'::jsonb, '["Contradição leva a nova votação (e não a nulidade imediata)."]'::jsonb, 'Duas respostas se contradizem, e os jurados votam novamente.', '["Assertiva que anula o julgamento diante de contradição sem nova votação erra."]'::jsonb, '[]'::jsonb, '["Art. 483"]'::jsonb, 'under_review', 'claude'
