insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em seguida, o presidente proferirá sentença. No caso de condenação: fixará a pena-base; considerará as circunstâncias agravantes ou atenuantes alegadas nos debates; imporá os aumentos ou diminuições, em atenção às causas admitidas pelo júri; observará as demais disposições do art. 387; mandará o acusado recolher-se ou o recomendará à prisão em que se encontra, se presentes os requisitos da preventiva, ou, no caso de condenação a pena igual ou superior a 15 anos de reclusão, determinará a execução provisória das penas, com expedição de mandado de prisão, sem prejuízo do conhecimento de recursos; e estabelecerá os efeitos genéricos e específicos da condenação. No caso de absolvição, mandará colocar em liberdade o acusado se por outro motivo não estiver preso, entre outras providências.', '["Condenação: pena-base, agravantes e atenuantes alegadas, aumentos e diminuições, art. 387.","Prisão: se presentes os requisitos da preventiva; pena igual ou superior a 15 anos: execução provisória.","Efeitos genéricos e específicos da condenação.","Absolvição: liberdade, se por outro motivo não estiver preso."]'::jsonb, '["Pena igual ou superior a 15 anos: execução provisória (texto do dispositivo), tema debatido no STF.","O juiz presidente fixa a pena; os jurados decidem apenas sobre os fatos."]'::jsonb, 'O juiz presidente fixa a pena-base após o veredicto condenatório.', '["Assertiva que atribui aos jurados a fixação da pena erra: ela cabe ao juiz presidente."]'::jsonb, '[]'::jsonb, '["Art. 387","Art. 483"]'::jsonb, 'under_review', 'claude'
