insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos crimes de responsabilidade dos funcionários públicos, cujo processo e julgamento competirão aos juízes de direito, a queixa ou a denúncia será instruída com documentos ou justificação que façam presumir a existência do delito ou com declaração fundamentada da impossibilidade de apresentação de qualquer dessas provas.', '["Crimes de responsabilidade de funcionários públicos julgados por juiz de direito.","Denúncia ou queixa instruída com documentos ou justificação.","Ou declaração fundamentada de impossibilidade."]'::jsonb, '["Início do procedimento especial dos crimes funcionais afiançáveis."]'::jsonb, 'A denúncia contra o servidor vem acompanhada de documentos que indicam o delito.', '["Assertiva que dispensa documentos ou justificação para a denúncia do art. 513 erra."]'::jsonb, '[]'::jsonb, '["Art. 514"]'::jsonb, 'under_review', 'claude'
