on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No caso do artigo anterior, durante o prazo concedido para a resposta, os autos permanecerão em cartório, onde poderão ser examinados pelo acusado ou por seu defensor. A resposta poderá ser instruída com documentos e justificações.', '["Autos permanecem em cartório durante o prazo de resposta.","Acusado ou defensor podem examiná-los.","Resposta pode ter documentos e justificações."]'::jsonb, '["Acesso aos autos em cartório."]'::jsonb, 'O defensor examina os autos em cartório e junta documentos à resposta.', '["Assertiva que impede o exame dos autos durante o prazo de resposta erra."]'::jsonb, '[]'::jsonb, '["Art. 514"]'::jsonb, 'under_review', 'claude'
