select u.id, u.content_sha256, 'Nos casos das infrações previstas nos §§ 1º, 2º e 3º do art. 184 do Código Penal (violação de direitos autorais), a autoridade policial procederá à apreensão dos bens ilicitamente produzidos ou reproduzidos, em sua totalidade, juntamente com os equipamentos, suportes e materiais que possibilitaram a sua existência, desde que estes se destinem precipuamente à prática do ilícito.', '["Violação de direitos autorais: apreensão pela autoridade policial.","Bens ilicitamente produzidos ou reproduzidos, em sua totalidade.","Equipamentos, suportes e materiais destinados precipuamente ao ilícito."]'::jsonb, '["Apreensão integral dos bens e dos equipamentos destinados ao ilícito."]'::jsonb, 'A polícia apreende as cópias piratas e os equipamentos de reprodução.', '["Assertiva que limita a apreensão a uma amostra dos bens ilícitos erra: é em sua totalidade."]'::jsonb, '[]'::jsonb, '["Art. 184 do Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-530-b'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na ocasião da apreensão será lavrado termo, assinado por 2 ou mais testemunhas, com a descrição de todos os bens apreendidos e informações sobre suas origens, o qual deverá integrar o inquérito policial ou o processo.', '["Termo de apreensão assinado por 2 ou mais testemunhas.","Descrição de todos os bens e informações sobre suas origens.","Integra o inquérito ou o processo."]'::jsonb, '["Duas ou mais testemunhas."]'::jsonb, 'O termo de apreensão lista os bens e é assinado por duas testemunhas.', '["Assertiva que dispensa testemunhas no termo de apreensão erra."]'::jsonb, '[]'::jsonb, '["Art. 530-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-530-c'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Subsequente à apreensão, será realizada, por perito oficial, ou, na falta deste, por pessoa tecnicamente habilitada, perícia sobre todos os bens apreendidos e elaborado o laudo que deverá integrar o inquérito policial ou o processo.', '["Perícia sobre todos os bens apreendidos.","Perito oficial ou, na falta, pessoa tecnicamente habilitada.","Laudo integra o inquérito ou o processo."]'::jsonb, '["Perícia de TODOS os bens apreendidos."]'::jsonb, 'Um perito oficial examina os bens apreendidos e elabora o laudo.', '["Assertiva que restringe a perícia a uma amostra dos bens erra."]'::jsonb, '[]'::jsonb, '["Art. 530-C"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-530-d'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os titulares de direito de autor e os que lhe são conexos serão os fiéis depositários de todos os bens apreendidos, devendo colocá-los à disposição do juiz quando do ajuizamento da ação.', '["Titulares de direitos autorais e conexos são fiéis depositários dos bens apreendidos.","Devem colocá-los à disposição do juiz quando da ação."]'::jsonb, '["Os próprios titulares guardam os bens."]'::jsonb, 'A associação titular dos direitos guarda os bens apreendidos até a ação.', '["Assertiva que torna a polícia a depositária dos bens apreendidos nesses crimes erra."]'::jsonb, '[{"termo":"Fiel depositário","significado":"Quem guarda o bem à disposição do juízo."}]'::jsonb, '["Art. 530-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-530-e'
