insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ressalvada a possibilidade de se preservar o corpo de delito, o juiz poderá determinar, a requerimento da vítima, a destruição da produção ou reprodução apreendida quando não houver impugnação quanto à sua ilicitude ou quando a ação penal não puder ser iniciada por falta de determinação de quem seja o autor do ilícito.', '["Destruição da produção ou reprodução apreendida, a requerimento da vítima.","Cabimento: sem impugnação da ilicitude, ou impossibilidade de iniciar a ação por falta de autoria determinada.","Ressalvada a preservação do corpo de delito."]'::jsonb, '["Preservar o corpo de delito."]'::jsonb, 'Sem autoria determinada, o juiz autoriza a destruição das cópias ilícitas.', '["Assertiva que destrói os bens sem preservar o corpo de delito erra."]'::jsonb, '[]'::jsonb, '["Art. 530-G"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-530-f'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz, ao proferir a sentença condenatória, poderá determinar a destruição dos bens ilicitamente produzidos ou reproduzidos e o perdimento dos equipamentos apreendidos, desde que precipuamente destinados à produção e reprodução dos bens, em favor da Fazenda Nacional, que deverá destruí-los ou doá-los aos Estados, Municípios e Distrito Federal, a instituições públicas de ensino e pesquisa ou de assistência social, bem como incorporá-los, se houver interesse, ao patrimônio da União, que não poderá retorná-los aos canais de comércio.', '["Sentença condenatória: destruição dos bens ilícitos.","Perdimento dos equipamentos destinados precipuamente à produção.","Destino: Fazenda Nacional destrói, doa a entes e instituições ou incorpora ao patrimônio da União.","Não retornam aos canais de comércio."]'::jsonb, '["Os bens não podem voltar ao comércio."]'::jsonb, 'Na condenação, os equipamentos de reprodução são perdidos em favor da Fazenda Nacional.', '["Assertiva que permite o retorno dos bens ao comércio erra."]'::jsonb, '[]'::jsonb, '["Art. 530-F"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-530-g'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As associações de titulares de direitos de autor e os que lhes são conexos poderão, em seu próprio nome, funcionar como assistente da acusação nos crimes previstos no art. 184 do Código Penal, quando praticado em detrimento de qualquer de seus associados.', '["Associações de titulares de direitos autorais e conexos podem ser assistentes da acusação, em nome próprio.","Crimes do art. 184 do CP, em detrimento de associados."]'::jsonb, '["Legitimidade da associação como assistente."]'::jsonb, 'A associação de autores atua como assistente da acusação em crime contra seus associados.', '["Assertiva que nega às associações a possibilidade de atuar como assistente da acusação erra."]'::jsonb, '[]'::jsonb, '["Art. 268"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-530-h'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

