select u.id, u.content_sha256, 'Nos crimes em que caiba ação penal pública incondicionada ou condicionada, observar-se-ão as normas constantes dos arts. 530-B, 530-C, 530-D, 530-E, 530-F, 530-G e 530-H.', '["Ação penal pública (incondicionada ou condicionada): aplicam-se os arts. 530-B a 530-H."]'::jsonb, '["Os arts. 524 a 530 valem para a queixa; os 530-B a 530-H, para a ação pública."]'::jsonb, 'Em crime de ação pública contra direitos autorais, aplicam-se as regras de apreensão e perícia dos arts. 530-B a 530-H.', '["Assertiva que aplica os arts. 524 a 530 aos crimes de ação pública erra."]'::jsonb, '[]'::jsonb, '["Art. 530-A"]'::jsonb, 'under_review', 'claude'
