insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na audiência de instrução e julgamento do procedimento sumário, a ser realizada no prazo máximo de 30 dias, proceder-se-á à tomada de declarações do ofendido, se possível, à inquirição das testemunhas arroladas pela acusação e pela defesa, nesta ordem, ressalvado o art. 222, bem como aos esclarecimentos dos peritos, às acareações e ao reconhecimento de pessoas e coisas, interrogando-se, em seguida, o acusado e procedendo-se o debate.', '["Audiência no prazo máximo de 30 dias (procedimento sumário).","Ordem: ofendido, testemunhas da acusação e da defesa, peritos, acareações, reconhecimentos, interrogatório e debate."]'::jsonb, '["Prazo: 30 dias (no ordinário, 60 dias)."]'::jsonb, 'No rito sumário, a audiência ocorre no prazo máximo de 30 dias.', '["Assertiva que fixa em 60 dias o prazo da audiência no rito sumário erra: são 30 dias."]'::jsonb, '[]'::jsonb, '["Art. 400","Art. 532"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-531'
